-- 022: researched program requirements, class profiles and employment data (collected 2026-11-16)
on conflict (school_name,program_name) do update set degree_type=excluded.degree_type,format=excluded.format,duration=excluded.duration,intake=excluded.intake,program_url=excluded.program_url,data=excluded.data,class_profile=excluded.class_profile,employment=excluded.employment;
