insert into public.program_requirements(school_name,program_name,degree_type,format,duration,intake,program_url,data,class_profile,employment) values
('Harvard Business School','MBA (Class of 2029)','mba','full-time','2 years (per HBS site tagline ''Two Years''; not stated on admissions pages read)','Fall 2027','https://www.hbs.edu/mba/admissions','{"deadlines": {"value": "Class of 2029 (fall 2027): Round One submit by Sept 9, 2026 12:00 PM ET, decision Dec 10, 2026; Round Two submit by Jan 5, 2027 12:00 PM ET, decision Mar 25, 2027. Apply in one round only.", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": null, "tests": {"value": "Must take GRE or GMAT before applying; no preference between them; no GMAT/GRE waivers; if multiple scores are submitted only the highest single sitting is considered; unofficial scores accepted at submission, official scores must be sent to HBS. Executive Assessment not mentioned on pages read. No minimum score stated.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages below 7.5", "toefl_min": "No minimum to apply; discouraged below 109 iBT (or 5 on the 1-6 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required unless undergraduate institution''s sole language of instruction was English; if a graduate degree was taught in English, a test is recommended but not required", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": {"items": [], "note": "2026-27 MBA Application Guide describes the section only as: ''Submit three short essays. This is your opportunity to share meaningful or formative experiences that are important to you ... that you haven''t gotten a chance to fully explore elsewhere in your application.'' Exact prompts and word limits are not published in the guide or on the Application Process page.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "video_assessment": null, "interview": {"value": "By invitation only; 30 minutes with an MBA Admissions Board member who has reviewed the application; on campus, in hub cities, or via Zoom (format does not affect candidacy); invited candidates must interview and submit a written reflection within 24 hours.", "source_url": "https://www.hbs.edu/mba/admissions/application-process"}, "recommendations": {"value": "Two recommenders; HBS prefers one be a current or former supervisor. Recommenders answer two prompts (how the applicant compares to other well-qualified people in similar roles; most important constructive feedback given). Due at application deadline with 48-hour grace period for recommenders only.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "other_requirements": {"value": "Resume/CV in simple business format; transcripts from every institution where a degree was earned (unofficial accepted at application); US bachelor''s equivalent required (3-year international bachelor''s qualifies); describe three most recent jobs; up to 3 awards and 3 activities; Post-MBA Goals section; three short essays. Interview invitation requires a post-interview written reflection within 24 hours. Minimum work experience not stated on pages read.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "notes": "Application fee amount and the exact essay prompt/word limit were not stated on any HBS page fetched (the 2026-27 guide says three short essays on meaningful or formative experiences not explored elsewhere, with no prompts or limits listed). Need-based fee waiver exists. Duolingo is accepted for HBS. Admit-stage: official original-language paper transcripts from each institution must be sent directly to WES with an official word-for-word English translation; offer may be withdrawn if unofficial and official versions differ. All materials in English. Duration of 2 years is not stated on pages read except the MBA menu tagline ''Two Years'' on the joint degree page; verify."}'::jsonb,'{"class_label": "Class of 2027 (entering fall 2025); Class of 2028 profile not found", "gmat_avg": null, "gmat_median": 730, "gmat_range": "690-770 (GMAT Classic; per Poets&Quants, range type not specified, likely middle 80%); 28% submitted Classic", "gmat_focus_median": 685, "gmat_focus_range": "645-735 (middle 80%, per Poets&Quants); 34% submitted Focus", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "Median 164 V and 164 Q (Clear Admit); median total 328 (Poets&Quants); no range found", "gpa_avg": 3.76, "gpa_range": null, "work_exp_avg_years": 4.9, "work_exp_range": null, "class_size": 943, "international_pct": 37, "women_pct": 44, "countries": 62, "pct_submitted_gre": 44, "source_url": "https://www.clearadmit.com/2025/11/harvard-mba-class-of-2027-profile/ ; https://poetsandquants.com/2025/11/19/in-its-latest-mba-class-profile-clues-to-what-it-takes-to-get-into-harvard-business-school/", "source_name": "Clear Admit and Poets&Quants summaries of HBS class profile (official HBS page not fetched)"}'::jsonb,'{"report_label": "Class of 2025 employment report", "employed_3_months_pct": null, "median_base_salary": "USD 184,500", "mean_base_salary": null, "top_industries": "Financial services 34%, Technology 22%, Consulting 21%, Health care 6%, Manufacturing 5%", "top_employers": null, "international_employed_note": "65% of 929-member class sought employment; 90% of seekers had an offer within 3 months (about 94% by mid-November); Clear Admit says 84% accepted a job within 3 months (denominator unclear). 92% of graduates worked in the US, 8% abroad. No visa info.", "source_url": "https://www.clearadmit.com/2025/12/hbs-mba-class-of-2025-employment-report/ ; https://www.hbs.edu/mba/blog/class-of-2025-employment-report", "source_name": "Clear Admit; HBS MBA blog (blog confirms 90% offers at 3 months, no salary)"}'::jsonb),
('Harvard Business School','MBA 2+2 Deferred Admission','mba','full-time','2 years MBA after 2-4 years of required work experience (deferral max 4 years)','Deferred; matriculation year not stated','https://www.hbs.edu/mba/admissions/application-process/college-students-2-2/2-2-application-process','{"deadlines": {"value": "Single 2+2 submission deadline April 28, 2027 12:00 PM ET (application opens December 2026); decision date to be announced. Not rolling.", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": {"value": "None for 2+2 applicants", "source_url": "https://www.hbs.edu/mba/admissions/application-process/college-students-2-2/2-2-application-process"}, "tests": {"value": "A valid GMAT or GRE score is required (which one not specified on page).", "source_url": "https://www.hbs.edu/mba/admissions/application-process/college-students-2-2/2-2-application-process"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages scores below 7.5", "toefl_min": "No minimum to apply; discouraged below 5 (new 1-6 scale) or 109 (0-120 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required if undergraduate institution did not use only English for instruction. Not required if undergraduate instruction was solely in English; a graduate degree taught in English makes testing optional but recommended. 2+2 page says international applicants from non-English-speaking undergraduate universities must submit an English test. HBS TOEFL code 3444.", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": null, "video_assessment": null, "interview": null, "recommendations": {"value": "All recommendations submitted online; number not stated on page.", "source_url": "https://www.hbs.edu/mba/admissions/application-process/college-students-2-2/2-2-application-process"}, "other_requirements": {"value": "Eligibility: final-year bachelor''s or joint bachelor/master''s student graduating between Oct 1, 2026 and Sept 30, 2027; master''s candidates only if direct from undergrad with no full-time job. If admitted: $1,000 USD non-refundable tuition deposit, withdraw other MBA applications, complete at least 2 years of full-time work in an HBS-approved position (max 4-year deferral).", "source_url": "https://www.hbs.edu/mba/admissions/application-process/college-students-2-2/2-2-application-process"}, "notes": "Relevant only to students in their final undergraduate year; not for Octavia-type working professionals. Essays/interview not described on page."}'::jsonb,null,null),
('Harvard Business School','MS/MBA Biotechnology: Life Sciences (HBS + Harvard GSAS)','mba','full-time','2 academic years plus August, and January-term coursework','Fall 2027 (assumed to follow the MBA cycle; not stated)','https://www.hbs.edu/mba/academic-experience/joint-degree-programs/life-sciences-harvard-graduate-school-arts-sciences','{"deadlines": {"value": "Joint degree pages give no dates; HBS Class of 2029 MBA rounds: Sept 9, 2026 and Jan 5, 2027 (12:00 PM ET).", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": null, "tests": {"value": "Must take GRE or GMAT before applying; no preference between them; no GMAT/GRE waivers; if multiple scores are submitted only the highest single sitting is considered; unofficial scores accepted at submission, official scores must be sent to HBS. Executive Assessment not mentioned on pages read. No minimum score stated.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages below 7.5", "toefl_min": "No minimum to apply; discouraged below 109 iBT (or 5 on the 1-6 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required unless undergraduate institution''s sole language of instruction was English; if a graduate degree was taught in English, a test is recommended but not required", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": {"items": [], "note": "Page states MBA: one essay; Master of Science: one required supplemental essay and one optional essay. Prompts and word limits are not given on the page.", "source_url": "https://www.hbs.edu/mba/academic-experience/joint-degree-programs/life-sciences-harvard-graduate-school-arts-sciences/admissions-and-financial-aid"}, "video_assessment": null, "interview": {"value": "By invitation only; candidates not invited are denied. Invitations go out in October (Round 1) and February (Round 2). Interviewed candidates submit one additional recommendation for the MS portion, emailed with the interview invitation. Format not described on this page.", "source_url": "https://www.hbs.edu/mba/academic-experience/joint-degree-programs/life-sciences-harvard-graduate-school-arts-sciences/admissions-and-financial-aid"}, "recommendations": {"value": "Two recommenders; HBS prefers one be a current or former supervisor. Recommenders answer two prompts (how the applicant compares to other well-qualified people in similar roles; most important constructive feedback given). Due at application deadline with 48-hour grace period for recommenders only.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "other_requirements": {"value": "Joint degree applicants indicate it in the ''Start Application'' section of the HBS application; separate application and independent admission by the partner school.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "notes": "Seeks undergraduate life sciences degree and/or significant biotech/life sciences work experience. Application steps and partner-school process not stated on page read; see program Admissions & Financial Aid page. Standard HBS requirements likely apply but not confirmed. Test, English, and recommendation entries are the general HBS MBA rules; joint pages themselves do not restate them."}'::jsonb,null,null),
('Harvard Business School','MS/MBA Engineering Sciences (HBS + Harvard SEAS)','mba','full-time','4 semesters over 2 years plus summer and January term coursework (about 3/4 of a fifth semester)','Fall 2027 (assumed to follow the MBA cycle; not stated)','https://www.hbs.edu/mba/academic-experience/joint-degree-programs/ms-mba-engineering-sciences','{"deadlines": {"value": "Joint degree pages give no dates; HBS Class of 2029 MBA rounds: Sept 9, 2026 and Jan 5, 2027 (12:00 PM ET).", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": null, "tests": {"value": "Must take GRE or GMAT before applying; no preference between them; no GMAT/GRE waivers; if multiple scores are submitted only the highest single sitting is considered; unofficial scores accepted at submission, official scores must be sent to HBS. Executive Assessment not mentioned on pages read. No minimum score stated.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages below 7.5", "toefl_min": "No minimum to apply; discouraged below 109 iBT (or 5 on the 1-6 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required unless undergraduate institution''s sole language of instruction was English; if a graduate degree was taught in English, a test is recommended but not required", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": {"items": [], "note": "Page states MBA: one essay; Master of Science: one required supplemental essay and one optional essay. Prompts and word limits are not given on the page.", "source_url": "https://www.hbs.edu/mba/academic-experience/joint-degree-programs/ms-mba-engineering-sciences/ms-mba-engineering-sciences-admissions"}, "video_assessment": null, "interview": {"value": "By invitation only; candidates not invited are denied. Invitations go out in October (Round 1) and February (Round 2). Interviewed candidates submit one additional recommendation for the MS portion (technical capabilities and experience), emailed with the invitation. Format not described on this page.", "source_url": "https://www.hbs.edu/mba/academic-experience/joint-degree-programs/ms-mba-engineering-sciences/ms-mba-engineering-sciences-admissions"}, "recommendations": {"value": "Two recommenders; HBS prefers one be a current or former supervisor. Recommenders answer two prompts (how the applicant compares to other well-qualified people in similar roles; most important constructive feedback given). Due at application deadline with 48-hour grace period for recommenders only.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "other_requirements": {"value": "Joint degree applicants indicate it in the ''Start Application'' section of the HBS application; separate application and independent admission by the partner school.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "notes": "Whether a separate SEAS application is needed is not stated on page read. Test, English, and recommendation entries are the general HBS MBA rules; joint pages themselves do not restate them."}'::jsonb,null,null),
('Harvard Business School','MBA/MPP and MBA/MPA-ID (HBS + Harvard Kennedy School)','mba','full-time','3 years','Fall 2027 (assumed to follow the MBA cycle; not stated)','https://www.hbs.edu/mba/academic-experience/joint-degree-programs/harvard-kennedy-school','{"deadlines": {"value": "Joint degree pages give no dates; HBS Class of 2029 MBA rounds: Sept 9, 2026 and Jan 5, 2027 (12:00 PM ET).", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": null, "tests": {"value": "Must take GRE or GMAT before applying; no preference between them; no GMAT/GRE waivers; if multiple scores are submitted only the highest single sitting is considered; unofficial scores accepted at submission, official scores must be sent to HBS. Executive Assessment not mentioned on pages read. No minimum score stated.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages below 7.5", "toefl_min": "No minimum to apply; discouraged below 109 iBT (or 5 on the 1-6 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required unless undergraduate institution''s sole language of instruction was English; if a graduate degree was taught in English, a test is recommended but not required", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": {"items": [], "note": "Page says applicants submit a joint degree program essay to both schools. Prompt and word limit not given on the page.", "source_url": "https://www.hbs.edu/mba/academic-experience/joint-degree-programs/harvard-kennedy-school/harvard-kennedy-school-admissions"}, "video_assessment": null, "interview": {"value": "Apply to HBS and HKS separately. HBS general process: interview by invitation only, 30 minutes with an MBA Admissions Board member, on campus, in hub cities or via Zoom; written reflection due within 24 hours after the interview. (General HBS MBA page; joint-degree page does not describe interviews.)", "source_url": "https://www.hbs.edu/mba/admissions/application-process"}, "recommendations": {"value": "Two recommenders; HBS prefers one be a current or former supervisor. Recommenders answer two prompts (how the applicant compares to other well-qualified people in similar roles; most important constructive feedback given). Due at application deadline with 48-hour grace period for recommenders only.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "other_requirements": {"value": "Joint degree applicants indicate it in the ''Start Application'' section of the HBS application; separate application and independent admission by the partner school.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "notes": "Apply to HBS and HKS separately in the same cycle, each selects independently; indicate joint degree interest in each application and submit a joint degree essay to both schools. Listed by HBS as one page covering two degrees. Test, English, and recommendation entries are the general HBS MBA rules; joint pages themselves do not restate them."}'::jsonb,null,null),
('Harvard Business School','MD/MBA (HBS + Harvard Medical School)','mba','full-time','Not stated','Fall 2027 (assumed to follow the MBA cycle; not stated)','https://www.hbs.edu/mba/academic-experience/joint-degree-programs/harvard-medical-school','{"deadlines": {"value": "Joint degree pages give no dates; HBS Class of 2029 MBA rounds: Sept 9, 2026 and Jan 5, 2027 (12:00 PM ET).", "source_url": "https://www.hbs.edu/mba/admissions/application-dates"}, "application_fee": null, "tests": {"value": "Must take GRE or GMAT before applying; no preference between them; no GMAT/GRE waivers; if multiple scores are submitted only the highest single sitting is considered; unofficial scores accepted at submission, official scores must be sent to HBS. Executive Assessment not mentioned on pages read. No minimum score stated.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "english": {"ielts_min": "No minimum to apply; Admissions Board discourages below 7.5", "toefl_min": "No minimum to apply; discouraged below 109 iBT (or 5 on the 1-6 scale)", "duolingo": "accepted (no minimum to apply; discouraged below 145)", "pte_min": "No minimum to apply; discouraged below 75", "other_tests": null, "waiver": "Test required unless undergraduate institution''s sole language of instruction was English; if a graduate degree was taught in English, a test is recommended but not required", "source_url": "https://www.hbs.edu/mba/admissions/application-process/international-applicants"}, "essays": null, "video_assessment": null, "interview": {"value": "Apply to HBS and HMS separately. HBS general process: interview by invitation only, 30 minutes with an MBA Admissions Board member, on campus, in hub cities or via Zoom; written reflection due within 24 hours after the interview. (General HBS MBA page; joint-degree page does not describe interviews.)", "source_url": "https://www.hbs.edu/mba/admissions/application-process"}, "recommendations": {"value": "Two recommenders; HBS prefers one be a current or former supervisor. Recommenders answer two prompts (how the applicant compares to other well-qualified people in similar roles; most important constructive feedback given). Due at application deadline with 48-hour grace period for recommenders only.", "source_url": "https://www.hbs.edu/mba/blog/answering-your-questions-about-the-hbs-mba-application"}, "other_requirements": {"value": "Joint degree applicants indicate it in the ''Start Application'' section of the HBS application; separate application and independent admission by the partner school.", "source_url": "https://apply.hbs.edu/www/documents/HBS%20MBA%20Application%20Guide%202026-2027.pdf"}, "notes": "Apply to HBS and HMS separately; selected independently. Medical-school applicants; limited relevance for business applicants. Test, English, and recommendation entries are the general HBS MBA rules; joint pages themselves do not restate them."}'::jsonb,null,null),
