('Wharton','MBA (full-time)','mba','full-time','2 years','Fall 2027 (2026-27 cycle)','https://mba.wharton.upenn.edu/','{"deadlines": {"value": "2026-27 cycle, all 5:00 pm ET: Round 1 Sep 8, 2026; Round 2 Jan 5, 2027; Round 3 Mar 31, 2027; Deferred Admissions Apr 21, 2027 (11:59 pm ET). Late R1/R2 submissions roll to next round; late R3 not accepted.", "source_url": "https://mba.wharton.upenn.edu/applying/"}, "application_fee": {"value": "USD 275, non-refundable (waivers for active-duty/veteran US military)", "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "tests": {"value": "Submit either GMAT or GRE (test center or monitored at-home accepted); scores may be self-reported, official scores requested after an offer. No minimums stated. The page does not mention an Executive Assessment (EA) policy. Validity window by round (Round 1 accepts tests dated Sep 8, 2021 to Sep 8, 2026). 2026-27 cycle.", "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "accepted (no minimum published)", "pte_min": null, "other_tests": null, "waiver": "Test may be waived if you earned a degree from an institution where English was the language of instruction. Required otherwise: TOEFL iBT, PTE, IELTS or Duolingo English Test. Test date windows (2025-26 cycle): Round 1 Sep 8, 2024 to Sep 8, 2026; Round 2 Jan 5, 2025 to Jan 5, 2027; Round 3 Mar 31, 2025 to Mar 31, 2027. Page publishes no minimum scores.", "source_url": "https://mba.wharton.upenn.edu/application-guide/"}, "essays": {"items": [{"prompt": "What is your immediate post-MBA professional goal?", "limit": "50 words", "required": true}, {"prompt": "Describe your medium- and long-term professional goals after your Wharton MBA.", "limit": "150 words", "required": true}, {"prompt": "Taking into consideration your background – personal, professional, and/or academic – how do you plan to add meaningful value to the Wharton community?", "limit": "350 words", "required": true}, {"prompt": "Reapplicant essay: how you have reflected and grown since your previous application, with relevant updates to your candidacy.", "limit": "250 words", "required": false}, {"prompt": "Additional information: share any additional information about yourself that cannot be found elsewhere in your application (may address extenuating circumstances).", "limit": "500 words", "required": false}], "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "video_assessment": {"value": "Page does not mention a video requirement.", "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "interview": {"value": "By invitation only. Round 1 invitations Oct 28, 2026; Round 2 Feb 19, 2027; Round 3 Apr 16, 2027. Carey JD/MBA and Lauder invitees also complete a Wharton Team-Based Discussion plus a program interview.", "source_url": "https://mba.wharton.upenn.edu/applying/"}, "recommendations": {"value": "One letter, preferably from a current or former supervisor, using GMAC Common Letter of Recommendation. Carey JD/MBA applicants submit two letters.", "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "other_requirements": {"value": "One-page PDF resume (max 10 MB); transcripts from all undergraduate and graduate programs (unofficial or self-reported template accepted; official required on admission); page does not state a minimum work experience.", "source_url": "https://mba.wharton.upenn.edu/mba-application-requirements/"}, "notes": "Page lists no minimum English scores. Apply in Round 1 or 2 if you need a US student visa (Wharton guidance). Official transcripts/scores due after admission; check whether a credential evaluation is requested in the application (not stated on pages read). Cycle 2026-27."}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "Average 685 (GMAT Focus); no range found", "gre_verbal_avg": 163, "gre_quant_avg": 163, "gre_range": null, "gpa_avg": 3.7, "gpa_range": null, "work_exp_avg_years": 5, "work_exp_range": "1 to 15 years (official page)", "class_size": 858, "international_pct": 22, "women_pct": 41, "countries": 63, "pct_submitted_gre": null, "source_url": "https://www.clearadmit.com/2026/11/wharton-mba-class-of-2028-profile/ ; https://mba.wharton.upenn.edu/class-profile", "source_name": "Clear Admit (official Wharton page only rendered work experience; its numeric stats were placeholders)"}'::jsonb,'{"report_label": "Class of 2025 career report", "employed_3_months_pct": 87.0, "median_base_salary": "USD 185,000", "mean_base_salary": null, "top_industries": "Financial Services 38.2%, Consulting 28.2%, Technology 15.3%, Health Care 3.8%, Venture Capital 2.8% (categories overlap with sub-industries like IB 14.2%, PE 13.4%)", "top_employers": "53 employers hired 2+; alphabetical examples: Goldman Sachs, McKinsey, BCG, Bain, Blackstone, KKR, J.P. Morgan, Morgan Stanley, Google, Microsoft, Amazon", "international_employed_note": "87.0% (529 of 608 seekers) accepted; page does not state timeframe. 6% of grads employed outside US (median USD 135,000; Asia 180,000, Europe 119,728). International students 31% of class. No visa info.", "source_url": "https://statistics.mbacareers.wharton.upenn.edu/wp-content/uploads/2025/12/2025-Career-Report.pdf", "source_name": "Wharton MBA 2025 Career Report (PDF)"}'::jsonb),
