('Chicago Booth','Chicago Booth Scholars (deferred Full-Time MBA)','mba','full-time','Defer 2-5 years, then Full-Time MBA (21 months)','Deferred; enrol after 2-5 years','https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars','{"deadlines": {"value": "Most recent published (2025-26 cycle): due Apr 2, 2026, 11:59 pm CT; decisions Jun 25, 2026. Main MBA page lists Scholars deadline Apr 1, 2027 (decision Jun 24, 2027) for 2026-27.", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "application_fee": {"value": "USD 250 fee waived for Scholars applicants", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars"}, "tests": {"value": "GMAT or GRE required; Focus Edition and shortened GRE accepted; self-report, official only if admitted.", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "english": {"ielts_min": "7 (academic version)", "toefl_min": "5.0 on the new scale (tests on/after 21 Jan 2026); 104 iBT (tests before 21 Jan 2026); 600 paper", "duolingo": "accepted (min 135)", "pte_min": "70 (PTE Academic)", "other_tests": null, "waiver": "Only some candidates ''may be required'' to submit proof. Applicants scoring below minimum may still apply; admission contingent on English proficiency shown in interview (if invited) or other language requirements. Scores valid 2 years; TOEFL code 1832-02.", "source_url": "https://chicagobooth.edu/mba/full-time/admissions/international-students"}, "essays": {"items": [{"prompt": "What do you plan to accomplish after graduation and prior to starting your MBA?", "limit": "not stated", "required": true}, {"prompt": "How will the Chicago Booth Scholars Program contribute to your short-term goals during your deferment period? (also asks how the MBA will support long-term goals)", "limit": "not stated", "required": true}, {"prompt": "Choose one of the community photos and explain how it connects to one of your own values.", "limit": "not stated", "required": true}], "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "video_assessment": null, "interview": {"value": "Invitation-only, one interview with Admissions staff, students or alumni.", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "recommendations": {"value": "Two letters: one from a supervisor, one academic or collaborator.", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "other_requirements": {"value": "Resume; unofficial transcripts; must be in final year of bachelor''s (or moving directly into a master''s); must stay employed full time during deferment; USD 600 annual deposit.", "source_url": "https://www.chicagobooth.edu/mba/early-career-programs/chicago-booth-scholars/application-process"}, "notes": "Eligibility is final-year undergraduates, so likely not applicable to an experienced professional. Booth does not help with US work visas. Dates are from the 2025-26 cycle page."}'::jsonb,null,null),
