('Columbia Business School','Professional MBA (ProMBA)','mba','part-time','8 to 10 semesters','Fall 2027 (first cohort, August 2027)','https://academics.business.columbia.edu/admissions/promba','{"deadlines": {"value": "Fall 2027 entry: Round 1 Nov 4, 2026; Round 2 Feb 11, 2027; Round 3 May 27, 2027.", "source_url": "https://academics.business.columbia.edu/admissions/promba"}, "application_fee": {"value": "USD 250, nonrefundable; fee waiver for active-duty US military.", "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "tests": {"value": "Self-reported GMAT (10th or Focus), Executive Assessment or GRE required at submission; official score if admitted; valid 5 years; highest score only. No minimum listed.", "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "english": null, "essays": {"items": [{"prompt": "Short answer 1: What is your immediate post-MBA professional goal?", "limit": "50 characters", "required": true}, {"prompt": "Short answer 2: plans for attending class from a distance (applicants outside the NY Tri-state area).", "limit": "50 characters", "required": true}, {"prompt": "Essay 1: career goals over the next three to five years and long-term dream job.", "limit": "500 words", "required": true}, {"prompt": "Essay 2: how you cultivate a sense of community and inclusivity within a team, with at least one specific example.", "limit": "500 words", "required": true}, {"prompt": "Optional: anything else the committee should know; bullets acceptable.", "limit": "not stated", "required": false}], "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "video_assessment": null, "interview": {"value": "By invitation only; applicants cannot request one.", "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "recommendations": {"value": "One recommendation for first-time applicants, ideally current supervisor; former supervisor or other senior professional associate acceptable. Applicant may not draft it; use institutional/professional email.", "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "other_requirements": {"value": "Bachelor''s degree or equivalent; transcripts from all institutions; resume (1 page ideal, 2 max); students average ~5 years work experience. Admitted students pay two nonrefundable deposits totaling USD 3,000.", "source_url": "https://academics.business.columbia.edu/admissions/promba/application-requirements"}, "notes": "No English test requirement stated on the ProMBA pages read; the full-time MBA FAQ says no language test is required, but confirm for ProMBA. Part-time/remote format: visa sponsorship suitability for international students not stated on pages read."}'::jsonb,null,null),
('Columbia Business School','Three-Year JD/MBA (with Columbia Law School)','mba','full-time','3 years','not stated','https://academics.business.columbia.edu/admissions/dual-degrees','{"deadlines": {"value": "Class entering August 2027: Early Decision November 2, 2026, 12:00 pm ET; Regular Decision February 15, 2027, 12:00 pm ET. Current first-year Columbia Law students must apply by the Business School''s August Entry Round 1 deadline (September 9, 2026 for August 2027 entry).", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-deadlines"}, "application_fee": {"value": "USD 250, nonrefundable; waivers for active-duty US military, eligible displaced persons, Peace Corps/Teach For All.", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-requirements"}, "tests": {"value": "GMAT-only or GRE-only application allowed; LSAT cannot be the sole basis and any LSAT taken must be reported. Scores taken between June 1, 2021 and February 2026 (as stated on page).", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-requirements"}, "english": null, "essays": {"items": [{"prompt": "Why do you feel the Columbia Three-Year JD/MBA Program is a good fit for you academically, culturally and professionally? Also career goals after the program.", "limit": "500 words", "required": true}, {"prompt": "Tell us about a time you exemplified leadership skills in an educational, professional or personal setting; how will those skills contribute to your Columbia education and profession.", "limit": "250 words", "required": true}], "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-requirements"}, "video_assessment": null, "interview": {"value": "By invitation only.", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-requirements"}, "recommendations": {"value": "Two letters required; one professional and one academic strongly encouraged.", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees/three-year-jdmba/application-requirements"}, "other_requirements": {"value": "Single application; resume up to 2 pages; register for LSAC CAS for transcripts; current 1L students applying for the three-year track must meet the Round 1 MBA deadline (no exceptions). Four-year JD/MBA 1L/2L students can use any of three round deadlines.", "source_url": "https://academics.business.columbia.edu/admissions/dual-degrees"}, "notes": "Deadlines and English requirements not on the pages read. Other CBS dual degrees (MBA/MS Engineering, MBA with MPH, MIA, MD, DDS, etc.) need separate applications and were not covered."}'::jsonb,null,null),
('Columbia Business School','MS in Financial Economics (MSFE)','masters','full-time','Two years (four semesters), STEM eligible','Fall (MS programs have fall admission only; year not stated on pages read)','https://academics.business.columbia.edu/msfe','{"deadlines": null, "application_fee": {"value": "USD 100, nonrefundable; waivers for active-duty US military and Peace Corps/Teach for America/China/India members.", "source_url": "https://academics.business.columbia.edu/msfe/admissions/application-requirements"}, "tests": {"value": "GMAT or GRE required (neither preferred); self-report/unofficial scan at application, official if admitted. No exceptions or waivers ''under any circumstances''. No minimum listed.", "source_url": "https://academics.business.columbia.edu/admissions/ms/frequently-asked-questions"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not stated", "pte_min": null, "other_tests": "TOEFL, PTE or IELTS required for international applicants; no minimum scores stated. Scores valid 2 years, must be valid at application; self-report at application, official scores if admitted.", "waiver": "Exempt only if you earned a degree from an institution where English is the language of instruction. ''We will not accept requests for exceptions to this policy.''", "source_url": "https://academics.business.columbia.edu/msfe/admissions/application-requirements"}, "essays": {"items": [{"prompt": "Describe your educational goals and the academic or professional achievements that contributed most to your development.", "limit": "250-500 words", "required": true}, {"prompt": "Indicate your expected career track and explain how the program will help you reach your goals (be specific).", "limit": "250-500 words", "required": true}], "source_url": "https://academics.business.columbia.edu/msfe/admissions/application-requirements"}, "video_assessment": null, "interview": null, "recommendations": {"value": "Two required from professors or managers/supervisors