('Dartmouth Tuck','MBA (full-time, residential)','mba','full-time','2 years','Fall 2027 (2026-27 application cycle)','https://www.tuck.dartmouth.edu/mba','{"deadlines": {"value": "2026-27 Tuck application: Round 1 Sep 24, 2026 (decision Dec 10, 2026); Round 2 Jan 5, 2027 (Mar 18, 2027); Round 3 Mar 24, 2027 (Apr 29, 2027), all 5 pm ET. Consortium: Oct 15, 2026 and Jan 5, 2027. Interview guaranteed if complete application (incl. scores and letters) by Sep 1, 2026 or Dec 1, 2026.", "source_url": "https://tuck.dartmouth.edu/admissions/important-dates"}, "application_fee": {"value": "USD 250, non-refundable, plus processing fees. Automatic and on-request waivers for eligible groups (request more than 2 business days before deadline).", "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "tests": {"value": "Self-report GMAT or GRE General Test (no preference); GMAT Superscore not accepted; no minimum score; official reports only on enrollment. Waiver possible with 2+ years post-graduate work experience and native English or English-medium bachelor''s, requested before applying (R1 Aug 12, 2026; R2 Nov 9, 2026; R3 Mar 5, 2027). EA not mentioned.", "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "accepted (no minimum published)", "pte_min": null, "other_tests": "Accepts TOEFL iBT, IELTS Academic, PTE Academic, Duolingo English Test; no preference among them; at-home versions accepted. Self-report scores; official reports only required on enrollment. TOEFL code D507.", "waiver": "Non-native speakers waived if they earned a bachelor''s degree from an institution where English is the sole language of instruction; no approval or documentation needed, tick the box in the Degrees section. Scores must be valid on submission date. Page lists no minimum scores.", "source_url": "https://www.tuck.dartmouth.edu/mba/admissions/apply"}, "essays": {"items": [{"prompt": "Goals: What led to your professional goals and your understanding of where you need to grow, and why Tuck is the right environment for that growth.", "limit": "2,000 characters", "required": true}, {"prompt": "Personal perspective: An aspect of who you are that is not fully reflected in your resume, and how it will enrich the Tuck community.", "limit": "2,000 characters", "required": true}, {"prompt": "Supporting others: A time supporting another person was difficult, how you responded, and what you learned.", "limit": "2,000 characters", "required": true}, {"prompt": "Reapplicants only: how you have strengthened your candidacy since last applying.", "limit": "2,000 characters", "required": false}, {"prompt": "Optional: additional information not addressed elsewhere.", "limit": "2,000 characters", "required": false}], "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "video_assessment": {"value": "Not mentioned on the applying page.", "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "interview": {"value": "Guaranteed interview for complete applications by Sep 1 or Dec 1, 2026; otherwise invitation only. 30-45 minutes, mostly with trained second-year Tuck Admissions Associates, behavioral questions based on resume. Virtual offered, limited on-campus.", "source_url": "https://tuck.dartmouth.edu/admissions/visit-interview"}, "recommendations": {"value": "Two letters of reference using GMAC Common Letter of Recommendation questions; current direct supervisor preferred; non-English letters must be translated by an outside service; must arrive by deadline.", "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "other_requirements": {"value": "Application form including short- and long-term goals (300 characters); transcripts for every school attended with certified English translations; last four employers with compensation and responsibilities; one-page resume encouraged.", "source_url": "https://tuck.dartmouth.edu/admissions/applying-to-tuck"}, "notes": "Joint/dual degrees (e.g. MBA/MPH, MD/MBA, SAIS, Fletcher, HKS) have no combined application: apply separately to each school (https://www.tuck.dartmouth.edu/mba/blog/mba-joint-and-dual-degrees-at-tuck). Essays are character-limited. Outside tools to create essay content violate policy."}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": 682, "gmat_median": null, "gmat_range": "mid-80%: 635-735; page does not say Classic or Focus (section averages shown: Verbal 85, Quant 85, DI 81); 27% submitted GMAT, 6% GMAT 10th Edition", "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": 161, "gre_quant_avg": 161, "gre_range": "V 155-166, Q 156-167 (mid-80%)", "gpa_avg": 3.5, "gpa_range": "mid-80%: 3.14-3.87 (4.0 scale)", "work_exp_avg_years": 6, "work_exp_range": "mid-80%: 4-9 years", "class_size": 282, "international_pct": 39, "women_pct": 46, "countries": 53, "pct_submitted_gre": 59, "source_url": "https://tuck.dartmouth.edu/admissions/class-profile", "source_name": "Tuck MBA class profile (international includes dual citizens and permanent residents; foreign nationals 29%; 53 countries counts citizenship, birth and work)"}'::jsonb,'{"report_label": "Class of 2025 employment outcomes (released 2025-12-09); share with offers within 3 months (accepted: 87%)", "employed_3_months_pct": 90, "median_base_salary": "USD 175,000", "mean_base_salary": null, "top_industries": "Consulting 41%, Financial services 27%, Technology 13%", "top_employers": null, "international_employed_note": "International students: 92% received an offer within 3 months, 88% accepted. Top locations NYC and Boston 27% each. No visa sponsorship data.", "source_url": "https://tuck.dartmouth.edu/news/articles/2025-employment-outcomes-reflect-strength-talent-and-versatility-of-tuck-mbas", "source_name": "Tuck news article on Class of 2025 employment outcomes"}'::jsonb),
('Dartmouth Tuck','Master of Health Care Delivery Science (MHCDS)','masters','hybrid','12 months','Aug 16, 2027 kickoff','https://mhcds.dartmouth.edu/','{"deadlines": {"value": "Round 1 Dec 1, 2026 (rolling decision, priority scholarship); Round 2 Feb 15, 2027 (decision Mar 24, 2027); Round 3 Apr 15, 2027 (decision May 29, 2027), 5 pm EST.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "application_fee": {"value": "USD 100, non-refundable; USD 5,000 enrollment deposit about 30 days after offer.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "tests": {"value": "GMAT/GRE not mentioned.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "No test scores or minimums listed. Page states all nonnative English speakers must demonstrate proficiency in spoken and written English, a formal evaluation may be required prior to acceptance, and applicants should contact the admissions director to discuss their situation.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "essays": {"items": [{"prompt": "Personal statement on significant experiences that shaped your decision and how the degree will help meet your goals.", "limit": "2 pages (500 words)", "required": true}], "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "video_assessment": {"value": "Not mentioned.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "interview": {"value": "By invitation only after application is complete; currently remote per page.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "recommendations": {"value": "Three required; direct supervisor preferred.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "other_requirements": {"value": "CV; statement of institutional support signed by supervisor (3 residencies, 25 nights, about 15 hours per week online); official transcripts (unofficial to review); at least 5 years of health care delivery or related work experience.", "source_url": "https://mhcds.dartmouth.edu/admissions/application-process/"}, "notes": "Run jointly by Tuck and Geisel faculty (address 100 Tuck Hall); the page does not say which school admits. Aimed at clinical and executive leaders with 10+ years of experience, so it may be borderline for ''exclude executive programs''. WES course-by-course evaluation required for degrees earned outside the US/Canada, which applies to Indonesian degrees."}'::jsonb,null,null),
('Michigan Ross','Full-Time MBA','mba','full-time','2 years','Fall 2027 (Class of 2029)','https://michiganross.umich.edu/graduate/full-time-mba','{"deadlines": {"value": "2026-27 cycle: Round 1 Sept 8, 2026; Round 2 Jan 4, 2027; Round 3 Mar 29, 2027.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/admissions-blog/2026/06/17/class-2029-new-essays-key-application"}, "application_fee": {"value": "USD 200, non-refundable (read on the requirements page, which displayed 2021-22 cycle content; confirm current amount). Waived for US military/veterans, certain service-program members, current U-M grad students, citizens of UN least-developed countries, recent Ross FT MBA applicants.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/application-requirements"}, "tests": {"value": "2026-27: GMAT Focus, GRE, or Executive Assessment accepted. Without a score, applicants may submit a Statement of Quantitative Academic Readiness (SQAR) focused solely on quantitative experience/education. FAQ: no minimum score; GMAT, GRE, MCAT, LSAT, PCAT, DAT also listed there.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/admissions-blog/2026/06/17/class-2029-new-essays-key-application"}, "english": {"ielts_min": "7 or higher (FAQ says ''strongly recommend'')", "toefl_min": "FAQ text reads ''strongly recommend a TOEFL score of 5 on the iBT'' (appears to be a typo or new-scale score; confirm with admissions)", "duolingo": "accepted (DET 120 or higher strongly recommended)", "pte_min": "70 or higher (strongly recommended)", "other_tests": null, "waiver": "Exempt if undergraduate degree is from an accredited institution where English was the sole language of instruction.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/faqs"}, "essays": {"items": [{"prompt": "What is your short-term career goal, and how do you plan to leverage the Ross MBA and its program offerings in your first role after graduation? Please be specific and answer both parts of this question.", "limit": "300 words", "required": true}, {"prompt": "Part 2 Impact and Growth (choose one, list at top): ''Think of a time something important did not go as planned. What did you do next?'' / ''What is something you worked on for an extended period of time (over 6 months)'' / ''Share an example of a specific situation when your actions created a positive impact on your community''", "limit": "200 words", "required": true}, {"prompt": "Optional: Is there something in your resume or application that needs a brief explanation?", "limit": "250 words (bullets allowed)", "required": false}], "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/admissions-blog/2026/06/17/class-2029-new-essays-key-application"}, "video_assessment": null, "interview": {"value": "By invitation only, conducted by a Ross current student or alum; invitations come a few weeks after the deadline (from requirements page showing older-cycle content).", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/application-requirements"}, "recommendations": {"value": "One recommendation via the GMAC Common Recommendation Form; current or former supervisor ideal (client, project manager or mentor as alternatives). Application incomplete until received.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/application-requirements"}, "other_requirements": {"value": "One-page resume; unofficial transcripts for all undergrad/grad study at application (official + WES authentication if admitted); US bachelor''s equivalent (3-year degrees accepted only from regions that typically lack 4-year degrees); no minimum work experience (average ~5 years). Consortium applicants have extra essays.", "source_url": "https://michiganross.umich.edu/graduate/full-time-mba/admissions/application-requirements"}, "notes": "Page content for fee, interview, recommender details and credential rules was served from an older cycle (2021-22); deadlines, essays and test policy are 2026-27. International applicants are strongly encouraged to apply in Round 1 or 2 for visa processing time. Non-English documents need certified literal translation; notarized copies not accepted; WES authentication required if admitted. Indonesian degree: confirm four-year S1 equivalence (ITB S1 is typically four years)."}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": null, "gmat_median": null, "gmat_range": "GMAT 10th Edition (Classic) not reported", "gmat_focus_median": 695, "gmat_focus_range": "avg 687; middle 80%: 645-725", "gre_verbal_avg": 160, "gre_quant_avg": 162, "gre_range": null, "gpa_avg": 3.5, "gpa_range": "median 3.58; range not given", "work_exp_avg_years": 5.8, "work_exp_range": "middle 80%: 3.0-9.1 years", "class_size": 357, "international_pct": 31, "women_pct": 38, "countries": 33, "pct_submitted_gre": null, "source_url": "https://poetsandquants.com/2026/10/21/michigan-ross-loses-a-quarter-of-its-international-mbas-in-one-year/", "source_name": "Poets&Quants (secondary; Ross''s own page fetched still showed Class of 2027: 379 students, GMAT Classic avg 731 (700-770), Focus avg 681 (635-725), GPA 3.43, 5.8 yrs, 39% women, 40% intl, 32 countries)"}'::jsonb,'{"report_label": "Class of 2025 full-time MBA career report; share with offers within 3 months (accepted: 84.3%)", "employed_3_months_pct": 86.1, "median_base_salary": "USD 170,000", "mean_base_salary": "USD 159,272", "top_industries": "Consulting 33.5%, Financial services 19.5%, Technology 13.1%, Healthcare 10.2%", "top_employers": "McKinsey, Boston Consulting Group, Amazon (266 companies hired a graduate or intern)", "international_employed_note": "Foreign nationals: offers at 3 months 81.6%, accepted 80.0% (vs 89.7% offers / 87.7% accepted for US citizens and PRs). No visa sponsorship data.", "source_url": "https://poetsandquants.com/2025/12/12/mba-jobs-2025-later-hires-for-michigan-ross-but-pay-holds-steady/", "source_name": "Poets&Quants on Ross Class of 2025 report; top employers from Ross news release"}'::jsonb),
('Michigan Ross','Weekend MBA (Part-Time MBA)','mba','part-time','2 years (weekend classes twice per month)','2026-27 cycle; start term not stated on page','https://michiganross.umich.edu/graduate/weekend-mba','{"deadlines": {"value": "2026-27 cycle: Early deadline Nov 30, 2026; Final deadline Jan 18, 2027. Rolling review, decisions about 6-8 weeks after complete application.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "application_fee": {"value": "USD 200, non-refundable; waivers for military/veterans, Peace Corps/AmeriCorps/Teach for All (within 5 yrs), current U-M grad students, UN least-developed-country citizens, recent Ross MBA applicants, Fulbright Scholars, and those who attend a Part-Time MBA event before applying.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "tests": {"value": "GMAT, GMAT Focus, GRE or Executive Assessment (at-home accepted); scores valid 5 years; no minimum stated. Alternatives: free Quantitative Readiness Course (80%+ on final exam within 60 days) or test waiver (e.g. business/economics/STEM degree with 3.4+ GPA; CPA/CFA; PhD/MD/JD; U-M alumni 3.2+ GPA).", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "english": {"ielts_min": "not listed", "toefl_min": "not listed (iBT, code 1839)", "duolingo": "accepted (no minimum stated)", "pte_min": "not listed", "other_tests": null, "waiver": "Exempt if undergraduate degree taught solely in English, or lived/worked/did daily business in an English-speaking country for at least 2 years.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "essays": {"items": [{"prompt": "Part 1: Describe your short-term career goal and how Ross''s action-based learning will help you reach it (be specific).", "limit": "300 words", "required": true}, {"prompt": "Part 2 (choose one): What makes you unique? / An example of overcoming a personal challenge / What makes you excited to get up each morning? / A time you made a difference in your community or for an individual", "limit": "200 words", "required": true}, {"prompt": "Optional: Is there something in your resume or application that needs a brief explanation?", "limit": "250 words", "required": false}], "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "video_assessment": {"value": "None listed. Requirements page (cycle with Nov 30, 2026 / Jan 18, 2027 deadlines) lists no video submission; only a virtual interview, by invitation after materials review.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "interview": {"value": "Virtual, by invitation only, after all materials are reviewed.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "recommendations": {"value": "One recommendation via GMAC Common Recommendation Form; current supervisor preferred.", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "other_requirements": {"value": "One-page resume; unofficial transcripts (official if admitted); US bachelor''s or international equivalent; 24 months full-time work experience highly recommended; AI use in essays must be cited (''Personal Communication'').", "source_url": "https://michiganross.umich.edu/graduate/weekend-mba/admissions/application-requirements"}, "notes": "Not eligible for F-1 or J-1 student status; non-US citizens must hold a status permitting part-time study. Likely unsuitable for an applicant needing a student visa."}'::jsonb,null,null),
('Michigan Ross','Online MBA','mba','online','about 2.5 to 3 years (average)','January 2027 and late August 2027 starts','https://michiganross.umich.edu/graduate/online-mba','{"deadlines": {"value": "January 2027 start: early Aug 10, 2026, final Sept 21, 2026. Late Aug 2027 start: early Mar 22, 2027, final May 10, 2027. Decisions about 6-8 weeks after complete.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "application_fee": {"value": "USD 200, non-refundable; same waiver list as Weekend MBA (including attending a Part-Time MBA event).", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "tests": {"value": "GMAT/GMAT Focus, GRE or Executive Assessment; valid 5 years; no minimum stated. Alternatives: test waiver (business/econ/STEM degree 3.4+ GPA; CPA/CFA; PhD/MD/JD; U-M alumni 3.2+) or free Quantitative Readiness Course (80%+).", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "english": {"ielts_min": "not listed", "toefl_min": "not listed (iBT, code 1839)", "duolingo": "accepted (no minimum stated)", "pte_min": "not listed", "other_tests": null, "waiver": "Exempt if undergraduate degree taught solely in English, or 2+ years living/working in an English-speaking country.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "essays": {"items": [{"prompt": "Part 1: What is your short-term career goal, and how will Ross'' philosophy in Action-Based Learning help you achieve it?", "limit": "300 words", "required": true}, {"prompt": "Part 2 (choose one): What makes you unique? / Can you provide a specific example of how you''ve overcome a personal challenge? / What makes you excited to get up each morning? / Describe a time when you made a difference in your community or with an Individual.", "limit": "200 words", "required": true}, {"prompt": "Optional: Is there something in your resume or application that needs a brief explanation?", "limit": "250 words", "required": false}], "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "video_assessment": {"value": "None listed. Requirements page lists no video submission; only a virtual interview, by invitation after materials review.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "interview": {"value": "Virtual, by invitation only, after materials reviewed.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "recommendations": {"value": "One recommendation via GMAC Common Recommendation Form.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "other_requirements": {"value": "One-page resume; unofficial transcripts (official on acceptance); US bachelor''s or international equivalent; work experience not required but 24 months recommended.", "source_url": "https://michiganross.umich.edu/graduate/online-mba/admissions/application-requirements"}, "notes": "Online format; part-time study does not give F-1 student visa eligibility (stated for Weekend MBA; Online MBA page does not state visa info). University cannot serve Crimea, Donetsk/Luhansk, Cuba, Iran, North Korea, Syria."}'::jsonb,null,null),
('Michigan Ross','Master of Accounting (MAcc)','masters','full-time','1 year','Fall term cohort per program page; application is for Class of 2028','https://michiganross.umich.edu/graduate/master-of-accounting','{"deadlines": {"value": "Current cycle (Class of 2028, per Ross blog Aug 2026): Round 1 Sept 11, 2026; Round 2 Oct 23, 2026. Later rounds not given in that post. The program''s own requirements page showed an older-cycle round table (see notes).", "source_url": "https://michiganross.umich.edu/graduate/one-year-masters/admissions-blog/2026/08/12/ross-oym-application-live-august-2026-updates"}, "application_fee": {"value": "USD 100, non-refundable (waivers for military/veterans, Peace Corps/AmeriCorps/Teach for All, current U-M grad students, UN least-developed-country citizens, Fulbright Scholars).", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "tests": {"value": "GMAT/GRE waived if cumulative undergraduate GPA is 3.30 or above (WES GPA for WES-evaluated applicants); committee may still request scores; may submit scores anyway. Scores valid 5 years. No minimum stated.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "english": {"ielts_min": "7.0 total (each section reviewed separately)", "toefl_min": "100 iBT total", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Exempt if entire undergraduate degree was taught in English at an accredited institution. Test must be within 2 years of deadline.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "essays": {"items": [{"prompt": "Career goals and motivation: How will the MAcc support your short- and long-term goals, and what led you to pursue a graduate business degree?", "limit": "200-word minimum; content beyond 300 words not reviewed", "required": true}, {"prompt": "Please describe two or three meaningful ways in which you have engaged in your communities.", "limit": "200 min / 300 cap", "required": true}, {"prompt": "Self-evaluation (three parts): strengths with examples; areas for development and efforts to address them; ability to work with others in teams with an example of positive contribution.", "limit": "150 min / 300 cap each", "required": true}, {"prompt": "Optional additional information", "limit": "500 words", "required": false}], "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "video_assessment": {"value": "Interview by video conference (see interview section). The Aug 2026 blog says the OYM application includes an asynchronous video interview (Kira not named); the MAcc page itself describes a live video interview.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "interview": {"value": "Invitation only, by video conference, up to ~20 minutes, with committee member or staff.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "recommendations": {"value": "One recommendation on the program-specific form; no family or personal acquaintances.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "other_requirements": {"value": "Resume; transcripts from all institutions (official if admitted); prerequisites: Financial Accounting, Managerial Accounting, Intermediate Financial Accounting, Statistics (C or better); US bachelor''s or equivalent. New Paton Summer Immersion pathway (Summer 2027) for non-accounting undergrads.", "source_url": "https://michiganross.umich.edu/graduate/master-of-accounting/admissions/application-requirements"}, "notes": "Fee USD 100 and requirement details from MAcc requirements page (round table there was 2023-24). Requirements pages were served from an older cycle than the Aug 2026 blog, so re-check current deadlines, fee and requirements on the live application. WES US-version Course-by-Course evaluation required for non-US degrees (allow 4-8 weeks). Certified literal English translations; notarized copies not accepted."}'::jsonb,'{"class_label": "Class of 2026", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": 3.7, "gpa_range": null, "work_exp_avg_years": null, "work_exp_range": null, "class_size": 84, "international_pct": null, "women_pct": 55, "countries": null, "pct_submitted_gre": null, "source_url": "https://michiganross.umich.edu/programs/master-of-accounting/class-profile", "source_name": "Ross MAcc class profile (citizenship: US 58%, China 24%, India 4%, South Korea 4%, Taiwan 4%, Canada 2%, others)"}'::jsonb,'{"report_label": "Class of 2025 Ross one-year master''s career results", "employed_3_months_pct": null, "median_base_salary": null, "mean_base_salary": "About USD 78,000 average starting salary (type of pay not specified)", "top_industries": "Mostly public accounting; also corporate accounting, advisory, financial services", "top_employers": "Deloitte, EY, KPMG, PwC, General Motors, Citi, Amazon, Domino''s", "international_employed_note": "95% had job offers within 6 months (not 3). No international or visa data.", "source_url": "https://michiganross.umich.edu/graduate/one-year-masters/admissions-blog/2026/04/24/career-results-ross-oym-graduates-strong", "source_name": "Ross one-year master''s admissions blog, April 2026"}'::jsonb),
('Michigan Ross','Master of Business Analytics (MBAn)','masters','full-time','1 year','Summer 2027 start (Class of 2028)','https://michiganross.umich.edu/graduate/master-of-business-analytics','{"deadlines": {"value": "Current cycle (Class of 2028, per Ross blog Aug 2026): Round 1 Sept 11, 2026; Round 2 Oct 23, 2026. Later rounds not given in that post. The program''s own requirements page showed an older-cycle round table (see notes).", "source_url": "https://michiganross.umich.edu/graduate/one-year-masters/admissions-blog/2026/08/12/ross-oym-application-live-august-2026-updates"}, "application_fee": {"value": "USD 100, non-refundable (plus USD 50 per additional One-Year Master''s program).", "source_url": "https://michiganross.umich.edu/graduate/master-of-business-analytics/admissions/application-requirements"}, "tests": {"value": "GMAT/GRE waived if cumulative undergraduate GPA is 3.30+; committee may request scores; scores valid 5 years.", "source_url": "https://michiganross.umich.edu/graduate/master-of-business-analytics/admissions/application-requirements"}, "english": {"ielts_min": "7.0 total (each section reviewed separately)", "toefl_min": "100 iBT total", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Exempt if entire undergraduate degree was taught in English at an accredited institution. Test must be within 2 years of deadline.", "source_url": "https://michiganross.umich.edu/graduate/master-of-business-analytics/admissions/application-requirements"}, "essays": {"items": [{"prompt": "How will the MBAn program support you in achieving your short- and long-term career goals? What led you to pursue a graduate degree in business?", "limit": "200 min / content beyond 300 not reviewed", "required": true}, {"prompt": "Michigan Ross deeply values student engagement beyond the classroom. Please describe two or three meaningful ways in which you have engaged in your communities.", "limit": "200 min / 300 cap", "required": true}, {"prompt