words", "required": true}, {"prompt": "Person, Place & Thing: Please share three images (a person, a place, a thing) for the Admissions Committee; single PDF.", "limit": "150 words per paragraph", "required": true}, {"prompt": "Additional Information (optional)", "limit": "250 words", "required": false}], "source_url": "https://www.stern.nyu.edu/programs-admissions/mba-programs/part-time-mba-manhattan/admissions/essays"}, "video_assessment": {"value": "No video essay or video assessment component is listed among the application requirements. Videos on the admissions page are informational only.", "source_url": "https://www.stern.nyu.edu/programs-admissions/mba-programs/part-time-mba-manhattan/admissions"}, "interview": {"value": "Rare; almost all decisions are made without an interview.", "source_url": "https://www.stern.nyu.edu/programs-admissions/mba-programs/part-time-mba-manhattan/admissions/deadlines-process"}, "recommendations": {"value": "One professional recommendation, ideally current direct supervisor; additional optional.", "source_url": "https://www.stern.nyu.edu/programs-admissions/mba-programs/part-time-mba-manhattan/admissions/resume-recommendation"}, "other_requirements": {"value": "Resume; four-year US bachelor''s or foreign equivalent; unofficial transcripts; no transfer credits.", "source_url": "https://www.stern.nyu.edu/programs-admissions/mba-programs/part-time-mba-manhattan/admissions/eligibility-selection"}, "notes": "Part-time study does not provide student visa eligibility (Stern states this); cannot apply through Consortium or to dual degrees. Likely unsuitable for an applicant needing an F-1 visa."}'::jsonb,null,null),
