urce_url": "https://www.stern.nyu.edu/programs-admissions/masters-programs/ms-accounting/admissions/deadlines-process"}, "interview": {"value": "Invitation-only, limited, not required; virtual, 15-30 minutes; decision about 3 weeks after.", "source_url": "https://www.stern.nyu.edu/programs-admissions/masters-programs/ms-accounting/admissions/deadlines-process"}, "recommendations": {"value": "One recommendation (academic or professional), submitted online.", "source_url": "https://www.stern.nyu.edu/programs-admissions/masters-programs/ms-accounting/admissions/recommendation"}, "other_requirements": {"value": "Four-year US bachelor''s or equivalent foreign degree; pre-enrollment required courses (see Pre-Enrollment Requirements page); resume and transcripts pages not read.", "source_url": "https://www.stern.nyu.edu/programs-admissions/masters-programs/ms-accounting/admissions/eligibility-selection"}, "notes": "Non-US citizens must apply by the Nov 15 deadline. Foreign degree must be equivalent to a US four-year bachelor''s."}'::jsonb,'{"class_label": "Entering class fall 2026", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "80% range: 615-705", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "V 156-167, Q 167-170 (80% range)", "gpa_avg": 3.56, "gpa_range": null, "work_exp_avg_years": 1.7, "work_exp_range": "32% have work experience; 1.7 years average among those", "class_size": 120, "international_pct": 44, "women_pct": 60, "countries": 12, "pct_submitted_gre": null, "source_url": "https://www.stern.nyu.edu/programs-admissions/masters-programs/ms-accounting/admissions/class-profile", "source_name": "NYU Stern MS Accounting class profile"}'::jsonb,'{"report_label": "2026 graduates: 96% had job offers within four months of graduation (not 3 months)", "employed_3_months_pct": null, "median_base_salary": null, "mean_base_salary": null, "top_industries": "Public accounting", "top_employers": "More than