('NYU Stern','Stern at NYU Abu Dhabi One-Year Full-Time MBA','mba','full-time','12 months (54 credits), January to December','January 2028','https://stern.nyuad.nyu.edu/programs-admissions/mba-program/','{"deadlines": {"value": "Application for January 2028 intake open; Jan 7 priority scholarship deadline (full deadline table not read).", "source_url": "https://stern.nyuad.nyu.edu/programs-admissions/mba-program/admissions"}, "application_fee": null, "tests": {"value": "GMAT, GRE, Executive Assessment, MCAT, LSAT or DAT accepted, no preference among them; no minimum standardized score required; test waiver may be requested if academic readiness can be shown otherwise.", "source_url": "https://stern.nyuad.nyu.edu/programs-admissions/mba-program/admissions/faqs/"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "accepted (no minimum published)", "pte_min": null, "other_tests": null, "waiver": "Fluency in English required; non-native speakers may show it via a degree taught in English or TOEFL, IELTS or Duolingo English Test results (valid two years). No minimum scores published on the page.", "source_url": "https://stern.nyuad.nyu.edu/programs-admissions/mba-program/admissions/faqs/"}, "essays": null, "video_assessment": null, "interview": {"value": "By invitation only; conducted virtually by trained admissions professionals who have read the full application.", "source_url": "https://stern.nyuad.nyu.edu/stern-at-nyuad-one-year-full-time-mba/mba-admissions/"}, "recommendations": {"value": "Two required: one must be from your current supervisor (explain in application if unobtainable); the second may be someone who knows you professionally and/or personally.", "source_url": "https://stern.nyuad.nyu.edu/programs-admissions/mba-program/admissions/faqs/"}, "other_requirements": {"value": "Bachelor''s degree (or equivalent) from accredited institution.", "source_url": "https://stern.nyuad.nyu.edu/programs-admissions/mba-program/admissions"}, "notes": "Abu Dhabi campus; checklist, fee, tests and essays pages were not read."}'::jsonb,null,null),
('UCLA Anderson','Full-Time MBA','mba','full-time','22 months','Fall 2027 (2026-27 application cycle)','https://www.anderson.ucla.edu/degrees/full-time-mba','{"deadlines": {"value": "2026-27 cycle: Round 1 Oct 1, 2026 (decision Dec 11, 2026); Round 2 Jan 6, 2027 (decision Mar 26, 2027); Round 3 Apr 7, 2027 (decision May 14, 2027).", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "application_fee": {"value": "USD 200 (nonrefundable fee amount as stated on page)", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "tests": {"value": "Test-optional: GMAT (incl. Focus), GRE or Executive Assessment accepted, or apply without a test and submit an essay showing quantitative readiness (coursework, quant work experience, CFA/CPA, expired score). No minimum score. Highest total score only, no superscoring. Official scores needed for admission, not for applying.", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "english": {"ielts_min": "7.0 minimum overall (UCLA minimum)", "toefl_min": "87 minimum (UCLA minimum)", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Waived if bachelor''s degree is from an institution where English was the sole language of instruction (verified via WHED). Work experience in English does not waive. Tests must be within 2 years and no later than round deadline; TOEFL and IELTS accepted with no preference. Test optionality does not apply to English tests.", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-mba/admissions/international-applicants"}, "essays": {"items": [{"prompt": "Describe your short- and long-term post-MBA goals, including your desired role, industry... (also asks how an MBA will support those goals and which UCLA Anderson resources you will rely on most). Page text is abbreviated after the ellipsis.", "limit": "250 words", "required": true}, {"prompt": "How will classmates describe you by graduation and what qualities or values do you want to be known for, including how you will demonstrate them as a leader and community member (paraphrased from page).", "limit": "250 words", "required": true}, {"prompt": "What is the first thing you would tell your classmates about yourself upon arriving at Anderson?", "limit": "50 words", "required": true}, {"prompt": "Optional: Are there any extenuating circumstances or additional context you would like to share with the Admissions committee?", "limit": "250 words max", "required": false}], "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "video_assessment": {"value": "No required video submission listed.", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "interview": {"value": "By invitation only after application review; required for admission. About 30 minutes, Zoom or in person, conducted by second-year MBA students; blind (interviewer sees resume only).", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "recommendations": {"value": "Two required for new applicants (direct supervisors preferred); reapplicants submit one new letter. Submitted online.", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "other_requirements": {"value": "Resume required (ideally 1 page, max 2); employment section of application; scanned transcripts for all post-secondary study (official hard copies only after interview invitation); completed bachelor''s degree; most admits have full-time work experience, very few with under 1-2 years. Without a test, a readiness essay is required.", "source_url": "https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}, "notes": "Indonesian applicants: grades are not converted to a 4.0 scale. Three-year degrees may be accepted if profile is strong. Need transcript and degree certificate in native language plus certified English translation (originals only after interview invitation). English waiver only if WHED lists English as sole language of instruction; otherwise TOEFL/IELTS. F-1 I-20 after accepting offer. Source for notes: https://www.anderson.ucla.edu/degrees/full-time-mba/admissions/international-applicants and https://www.anderson.ucla.edu/degrees/full-time-MBA/admissions/requirements"}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": 718, "gmat_median": null, "gmat_range": "middle 80%: 650-750 (GMAT Classic 10th Edition)", "gmat_focus_median": null, "gmat_focus_range": "Focus Edition mean 660; middle 80%: 635-695", "gre_verbal_avg": 162, "gre_quant_avg": 164, "gre_range": "averages only: V 162, Q 164 (no range given)", "gpa_avg": 3.5, "gpa_range": "middle 80%: 3.1-3.9", "work_exp_avg_years": 5.4, "work_exp_range": "distribution: 0-3 yrs 21%, 3-6 yrs 53%, 6+ yrs 26%", "class_size": 287, "international_pct": 36, "women_pct": 39, "countries": 34, "pct_submitted_gre": null, "source_url": "https://www.anderson.ucla.edu/degrees/full-time-mba/admissions/class-profile", "source_name": "UCLA Anderson Full-Time MBA class profile page (countries=34 is for Classes of 2027 and 2028 combined; Clear Admit corroborates other figures)"}'::jsonb,'{"report_label": "Class of 2025 Full-Time MBA Employment Report (Parker Career Management Center)", "employed_3_months_pct": 74.7, "median_base_salary": "USD 160,096", "mean_base_salary": "USD 153,566", "top_industries": "Technology 28.3%, Consulting 25.6%, Financial Services 19.4%, Entertainment & Media 7.2%, Healthcare 5.6%, Consumer Products 5.6%", "top_employers": "4-9 hires: Mattel, Microsoft, Moelis, PwC, Santander, UBS, Wells Fargo, Amazon, others; 10-19 hires: Bank of America, BCG, Deloitte, McKinsey, Bain, Citi, Google, Apple, Jefferies, L.E.K., others (2024-2025 FT + summer combined)", "international_employed_note": "3-month acceptance: 74.5% permanent US work authorization vs 75% non-permanent (123 of 290 reporting had non-permanent auth). Global placements 6.1% of hires (median base USD 104,907); US placements 93.9% (median USD 168,500). International citizens 45% of the entering class of that cohort, 40 countries. 3-month figure is job acceptance; 54.8% by graduation, 85% by 6 months.", "source_url": "https://www.anderson.ucla.edu/sites/default/files/document/2026-03/Class%20of%202025%20Employment%20Report%20PDF_0.pdf", "source_name": "UCLA Anderson Class of 2025 FT MBA Employment Report PDF"}'::jsonb),
('UCLA Anderson','Fully Employed MBA (FEMBA)','mba','part-time','33 months','2026-27 application cycle (start term not stated on the page)','https://www.anderson.ucla.edu/degrees/fully-employed-mba','{"deadlines": {"value": "Round 1 due Oct 27, 2026 (interview day Nov 7, decision Dec 18, 2026); Round 2 due Jan 12, 2027 (interview day Jan 23, decision Mar 25, 2027); Round 3 due Apr 6, 2027 (interview day Apr 17, decision Jun 11, 2027).", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "application_fee": {"value": "USD 200", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "tests": {"value": "Required: GMAT, GRE or Executive Assessment; no preferred exam, no minimum. Can be waived by demonstrating academic achievement, e.g. a degree from an accredited US institution if criteria are met (criteria on a linked page, not read).", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "english": {"ielts_min": "7.0 overall band (IELTS Academic); some majors may set higher", "toefl_min": "87 overall (TOEFL iBT, exams before Jan 21, 2026); 4.5 for exams on or after Jan 21, 2026", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Exempt with a bachelor''s degree or higher from an accredited US university or from a country where English is the sole language of instruction (per WHED). Citizenship, US residence and work experience are not substitutes. Scores valid 2 years. FEMBA requirements page lists TOEFL iBT or IELTS Academic (no preference) and links to UCLA Graduate Division policy, where these minimums are published.", "source_url": "https://grad.ucla.edu/admissions/english-requirements/"}, "essays": {"items": [{"prompt": "Tell us about yourself and what you will bring to the learning community at UCLA Anderson.", "limit": "500 words", "required": true}, {"prompt": "What are your short and long term career goals and what aspects of UCLA Anderson will support you in achieving those goals?", "limit": "500 words", "required": true}, {"prompt": "Optional: Should the Admissions Committee be aware of any additional circumstances in your profile?", "limit": null, "required": false}], "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "video_assessment": {"value": "No video submission requirement stated.", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "interview": {"value": "Optional phone interview with a volunteer current student or alumnus, on the designated day of each round; not participating does not hurt the application.", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "recommendations": {"value": "Two required, preferably direct supervisor/manager; submitted online.", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "other_requirements": {"value": "Updated resume required; completed four-year bachelor''s or equivalent; official transcripts ordered before submitting (e-transcripts preferred); students average about 7 years of work experience, no minimum stated. Reapplicants: one new recommendation plus reapplicant essay.", "source_url": "https://www.anderson.ucla.edu/degrees/fully-employed-mba/admissions/requirements"}, "notes": "Part-time, employed in the Los Angeles area; page does not discuss F-1 visa eligibility for part-time study, so check with the school before applying from abroad."}'::jsonb,null,null),
('UCLA Anderson','Master of Financial Engineering (MFE)','masters','full-time','15 months','September 2027 (2027-28 application)','https://www.anderson.ucla.edu/degrees/master-of-financial-engineering','{"deadlines": {"value": "Admissions page (''application now open for 2027-28''): Round 1 Nov 30, 2026; Round 2 Jan 31, 2027; Round 3 Apr 1, 2027. The Requirements page separately says applications are accepted mid-September to end of April and calls the final round deadline April 30 (late only with committee approval). Conflict between pages; confirm with school.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions"}, "application_fee": {"value": "USD 200, nonrefundable", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "tests": {"value": "GMAT or GRE required; only applicants with a PhD are exempt. No minimum score; valid 5 years; highest score counts. Applications reviewed only in the round official scores are received. Class profile medians: GRE V159/Q169, GMAT 675.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "english": {"ielts_min": "7.0 minimum overall (page: ''minimum overall score required for IELTS is 7.0'')", "toefl_min": "87 (stated UCLA minimum); post-admission ESLPE waived with high TOEFL iBT/IELTS", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Exempt with bachelor''s+ from a US university or listed English-primary country (Australia, Barbados, Canada, Ireland, Jamaica, New Zealand, UK), or 2 years full-time study there, or WHED-verified sole-English-instruction degree. India/Singapore explicitly not exempt. TOEFL valid 2 years. Admitted students take ESLPE on arrival (failing cancels admission) unless high TOEFL/IELTS.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/international-applicants"}, "essays": {"items": [{"prompt": "Financial engineering requires a combination of mathematical/quantitative abilities and creative thinking. Describe a project that shows your analytical and creative problem-solving, and explain why it interested you (paraphrased from page).", "limit": "750 words", "required": true}, {"prompt": "Why does a career in quantitative finance appeal to you? (explain why it fits your abilities and what you know about the field; paraphrased)", "limit": "750 words", "required": true}, {"prompt": "Optional: supplemental information relevant to your potential to succeed in the program.", "limit": "375 words", "required": false}], "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "video_assessment": {"value": "No video assessment requirement stated.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "interview": {"value": "By invitation only after the application is complete.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "recommendations": {"value": "Two required, online; professional or academic supervisors who know your work. Family, friends, coworkers inadmissible. Under 2 years experience may use academic recommenders. System shows a third slot; contact MFE admissions for guidance.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "other_requirements": {"value": "Resume/CV PDF; scanned transcripts from every institution since high school; at least four-year bachelor''s or equivalent (16 years of schooling for non-US); strong quantitative background (linear algebra, multivariate calculus, probability/statistics) and programming (C++/R/Python) considered; do not submit generic Graduate Division statement of purpose.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/requirements"}, "notes": "Indonesian applicants: 16 years of schooling required; do not convert GPA to 4.0; native-language transcript and degree certificate with certified English translations; Dashew Center I-20 after USD 2,000 enrollment fee requires Confidential Financial Statement with certified bank statements/award letters. Credential evaluation not mentioned. Sources: https://www.anderson.ucla.edu/degrees/master-of-financial-engineering/admissions/international-applicants"}'::jsonb,null,'{"report_label": "Graduates entering the workforce in 2025 (summary on MFE program page; earlier Employment Report page is Class of 2023)", "employed_3_months_pct": null, "median_base_salary": null, "mean_base_salary": null, "top_industries": null, "top_employers": "Class of 2023 offers include BlackRock, Goldman Sachs, JP Morgan, Morgan Stanley, Capital Group, Deloitte, EY, PIMCO, UBS, Wells Fargo (unranked)", "international_employed_note": "Program page: employment rate 91% and average total compensation USD 155,484 (student-reported); timing of the rate not defined. Class of 2023 report page: 95% hired within 6 months; average base USD 109,427; 15% employed in China/Hong Kong; regions SoCal 39%, East Coast 32%.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-financial-engineering", "source_name": "UCLA Anderson MFE program page and Employment Report page"}'::jsonb),
('UCLA Anderson','Master of Science in Business Analytics (MSBA)','masters','full-time','15 months','Fall 2027 (Class of 2028)','https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics','{"deadlines": {"value": "Application opens September 2026. Round 1 Jan 8, 2027; Round 2 Mar 5, 2027; Round 3 May 7, 2027. Tentative decision dates on the page show 2024 (stale).", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions"}, "application_fee": {"value": "USD 200 for all applicants (nonrefundable)", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "tests": {"value": "GMAT or GRE expected (page does not use the word required; waivers via MSBA Director of Admissions for extenuating circumstances, case by case). Expected: GPA 3.0+, GMAT 710 or GRE Quant 167; GMAT Focus minimum 665. Highest of two attempts used.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "english": {"ielts_min": "7.5 overall", "toefl_min": "100 iBT with sections Writing 25, Speaking 24, Reading 21, Listening 17 (new-scale tests from Jan 21 2026: admission minimum overall 5.0)", "duolingo": "not stated", "pte_min": null, "other_tests": "TOEFL iBT Home Edition, IELTS Indicator, IELTS Online counted in 2026-27", "waiver": "Exempt with bachelor''s+ from US or primarily English-speaking country, or 2 years full-time study there, or WHED-verified sole-English-instruction degree (since Fall 2025). India, Nigeria, Pakistan not exempt. Post-admission ESLPE unless TOEFL 100+/IELTS 7.5+.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "essays": {"items": [{"prompt": "Business analytics requires a combination of mathematical/quantitative abilities and creative thinking. Describe a project that shows your analytical and creative problem-solving, and why it was interesting to you (paraphrased).", "limit": "750 words", "required": true}, {"prompt": "Statement of Purpose: academic and professional background, skills, accomplishments, research interests, goals; why this graduate program is a good fit.", "limit": "not stated", "required": true}, {"prompt": "Personal Statement: personal motivation for applying to UCLA Anderson; relevant experiences, challenges or accomplishments.", "limit": "not stated", "required": true}], "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "video_assessment": null, "interview": {"value": "By invitation only; MSBA office contacts you after submission.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "recommendations": {"value": "Two required (professors, employers, managers who can assess quantitative skills and management potential); a third is optional.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "other_requirements": {"value": "Unofficial transcripts with application; official on admission. Prerequisites: bachelor''s, strong quant background (linear algebra, multivariate calculus, statistics/probability), some programming. Resume not mentioned on this page.", "source_url": "https://www.anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/faq"}, "notes": "Indonesian applicants: degrees from 3-year programs are generally not accepted (exceptions possible for Commonwealth degrees with quantitative focus). I-20 request after USD 2,000 deposit; program is STEM designated. FAQ labels the intake as both Class of 2027 and 2028 and some date labels are inconsistent."}'::jsonb,'{"class_label": "Class of 2026", "gmat_avg": 668, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": 169, "gre_range": "avg Quant 169 only (page shows ''93%'' beside it, undefined)", "gpa_avg": 3.7, "gpa_range": null, "work_exp_avg_years": 1.5, "work_exp_range": null, "class_size": 109, "international_pct": 79, "women_pct": 47, "countries": 15, "pct_submitted_gre": null, "source_url": "https://anderson.ucla.edu/degrees/master-of-science-in-business-analytics/admissions/class-profile", "source_name": "UCLA Anderson MSBA class profile page (average age 24; percentages next to GMAT 91% / GRE 93% not defined on page)"}'::jsonb,'{"report_label": "MSBA Class of 2024 Employment Report (file in 2026-07 folder; page labels it Class of 2024). 89 of 95 seeking accepted full-time roles (counts stated; no % stated)", "employed_3_months_pct": null, "median_base_salary": "USD 110,000", "mean_base_salary": "USD 107,835", "top_industries": "Technology 37.1%, Financial Services 20.2%, Consulting 10.1%, CPG 6.7%, Media/Entertainment 5.6%, Healthcare 3.4%, Manufacturing 3.4%", "top_employers": "Full-time: Amazon (6), Meta (4), Capital One (3), Copart (3)", "international_employed_note": "76 of 114 students in the profile had non-permanent US work authorization; non-permanent median base USD 120,000 (mean 112,297, n=44) vs permanent median USD 100,000. Note: report lists a North America median inconsistently (150,000 vs 115,000).", "source_url": "https://www.anderson.ucla.edu/sites/default/files/document/2026-07/2026MSBA%20Employment%20Report%20Updates%20R3.pdf", "source_name": "UCLA Anderson MSBA Employment Report PDF"}'::jsonb),
('Cornell Johnson','Cornell MBA (two-year, Ithaca)','mba','full-time','2 years','Fall 2027 (2026-27 cycle)','https://business.cornell.edu/admissions/graduate/mba/','{"deadlines": {"value": "2026-27: Round 1 Sept 17, 2026 (final notification Dec 9, 2026); Consortium early Oct 15, 2026; Round 2 Jan 5, 2027 (final Mar 26, 2027); Round 3 Apr 6, 2027 (final May 21, 2027). Deadline 11:59 PM ET. Deposit/official documents due Jan 29, Apr 30, Jun 4, 2027 respectively.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/important-dates/"}, "application_fee": {"value": "USD 250, nonrefundable; waivers for US military/veterans, Forte MBALaunch, Peace Corps, Teach for America, current Cornell students (request 3 business days before deadline)", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "tests": {"value": "GMAT, GMAT 10th Edition, GRE or Executive Assessment; no minimum. Waiver available for full-time MBA if you have a STEM/business/quant degree with 3.0 GPA, CPA/CFA, or full-time quant/analytical work; request at submission with a 100-word statement; not guaranteed. Scores valid 5 years.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "english": {"ielts_min": "7.0 overall, at least 7.0 in speaking and writing", "toefl_min": "100 iBT overall, at least 25 in each section", "duolingo": "accepted (min 120)", "pte_min": null, "other_tests": "TOEFL MyBest superscores and TOEFL Essentials not accepted; scores valid 2 years", "waiver": "Native citizens of US, UK, Ireland, Australia, New Zealand, South Africa, Ghana, Canada (not India, Pakistan, Philippines, Hong Kong, Singapore); degree from those countries; or degree from non-English-speaking country with official documentation that English was sole language of instruction. Residency/work experience do not qualify.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "essays": {"items": [{"prompt": "How do you intend to make a meaningful impact on the Johnson community? (Essay 1: Impact)", "limit": "350 words", "required": true}, {"prompt": "Create a table of contents for your life story. (Essay 2; slides/media/portfolio alternatives allowed, multimedia under 3 minutes, files up to 25 MB)", "limit": "350 words", "required": true}, {"prompt": "Goals statement (short answer): immediate post-MBA role, company, industry, 5-10 year goal, and how you will use Johnson''s resources.", "limit": "not stated", "required": true}, {"prompt": "Optional essay: clarify application details (required for reapplicants).", "limit": "350 words", "required": false}], "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "video_assessment": {"value": "No video interview mentioned; video is only an optional medium for Essay 2.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "interview": {"value": "By invitation; format not given on the page.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "recommendations": {"value": "One required, up to two allowed, using the GMAC Common Letter of Recommendation.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "other_requirements": {"value": "Resume valued (not listed as separate requirement) and used for waiver eligibility; unofficial transcripts to apply, official by deposit deadline; bachelor''s degree required; no full-time work minimum (typically about 5 years).", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "notes": "Indonesian applicants: non-English transcripts need certified English translation (WES recommended); international credential evaluations can support a test waiver; Park Fellowship is US citizens/PR only. Indonesia is not on the English waiver country list, so need TOEFL/IELTS/Duolingo unless degree was taught entirely in English with official documentation."}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": 645, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": "median undergrad GPA 3.32 (no range given)", "work_exp_avg_years": 5.5, "work_exp_range": null, "class_size": 266, "international_pct": 38, "women_pct": 38, "countries": 39, "pct_submitted_gre": null, "source_url": "https://www.clearadmit.com/2026/11/cornell-johnson-two-year-mba-class-of-2028-profile/", "source_name": "Clear Admit report on Cornell Johnson Class of 2028 (official Cornell page fetched only showed Class of 2025: 283 students, median GMAT 710, median GPA 3.35, work exp 5.4, women 43%, intl 42%, 39 countries). No GRE reported. Average age 29."}'::jsonb,'{"report_label": "Two-Year MBA Class of 2025 employment report (285 graduates, 239 seeking)", "employed_3_months_pct": 83, "median_base_salary": "USD 175,000", "mean_base_salary": "USD 158,426", "top_industries": "Financial Services 41%, Consulting 28%, Technology & Telecom 11%, CPG 5%, Healthcare/Pharma 4%, Manufacturing 4%, Energy/Utilities 2%, Other 8%", "top_employers": "Accenture, Amazon, Bain, BCG, Citi, Deloitte, EY, EY-Parthenon, Guggenheim, Jefferies, JP Morgan Chase, McKinsey, Microsoft, Moelis, Morgan Stanley, RBC, Wells Fargo", "international_employed_note": "83% accepted offers within 3 months (85% received offers). US work-authorized: 91% offers, avg base USD 160,449; non-US work-authorized: 77% offers, avg base USD 154,963. Avg signing bonus USD 39,795.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/career-outcomes/", "source_name": "Cornell SC Johnson MBA career outcomes page"}'::jsonb),
('Cornell Johnson','Johnson Cornell Tech Dual-Campus Track (Cornell MBA, Ithaca then NYC)','mba','full-time','21 months','Fall 2027 (via Cornell MBA application)','https://business.cornell.edu/admissions/graduate/mba/dual-campus/','{"deadlines": {"value": "No separate dates; same as two-year Cornell MBA (Round 1 Sept 17, 2026; Round 2 Jan 5, 2027; Round 3 Apr 6, 2027).", "source_url": "https://business.cornell.edu/admissions/graduate/mba/important-dates/"}, "application_fee": {"value": "Same as Cornell MBA: USD 250", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "tests": {"value": "Same as Cornell MBA: GMAT/GRE/EA, no minimum; waiver criteria as above.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "english": {"ielts_min": "7.0 overall, at least 7.0 speaking and writing", "toefl_min": "100 iBT, at least 25 each section", "duolingo": "accepted (min 120)", "pte_min": null, "other_tests": null, "waiver": "As Cornell MBA: native citizens of listed English-speaking countries, degree from those countries, or documented English-medium degree", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "essays": {"items": [{"prompt": "Same as Cornell MBA: Essay 1 Impact (350 words), Essay 2 Table of Contents (350 words), goals statement, optional essay (see Cornell MBA row).", "limit": "350 words", "required": true}], "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "video_assessment": {"value": "None mentioned (as Cornell MBA).", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "interview": {"value": "By invitation (as Cornell MBA).", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "recommendations": {"value": "One required, up to two (as Cornell MBA).", "source_url": "https://business.cornell.edu/admissions/graduate/mba/application-guide/mba-application-requirements-faqs/"}, "other_requirements": {"value": "Track within the two-year Cornell MBA: apply to the Cornell MBA and indicate interest in the track. Begin in Ithaca, required tech/digital summer internship after semester 2, then move to Cornell Tech NYC for a full year in place of a semester abroad. Not a separate application.", "source_url": "https://business.cornell.edu/admissions/graduate/mba/dual-campus/"}, "notes": "Not a separately admitted program; shares the Cornell MBA application."}'::jsonb,null,null),
('Cornell Johnson','Johnson Cornell Tech MBA (NYC, one-year)','mba','full-time','1 year','Summer 2027 (June start)','https://tech.cornell.edu/programs/masters-programs/johnson-cornell-tech-mba/','{"deadlines": {"value": "Summer 2027 cycle (all 11:59 AM EST): Priority Oct 8, 2026; Round 2 Jan 7, 2027; Rolling deadline Mar 4, 2027. Decisions within 7 weeks of round deadline. International applicants advised to apply by Round 2.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "application_fee": {"value": "USD 200, nonrefundable", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "tests": {"value": "GMAT, GRE or EA required; no minimum, highest score used. Waiver can be requested in test section with a 100-word statement; if denied, application stays incomplete until a score is submitted. Class of 2026 averages GMAT 675, GRE 157V/163Q.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "english": {"ielts_min": "7.0 overall", "toefl_min": "100", "duolingo": "accepted (equivalent to TOEFL 100; no specific Duolingo number given; MyBestScore not accepted)", "pte_min": null, "other_tests": null, "waiver": "Citizens of US, UK, Ireland, Australia, NZ, South Africa, Ghana, Canada (not India, Pakistan, Philippines, Hong Kong, Singapore); degree from those countries; or degree from non-English-speaking country with documentation English was sole language of instruction. Residency and work do not qualify.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "essays": {"items": [{"prompt": "At Cornell Tech, we value creative problem-solving under real-world constraints. Describe a specific time you creatively solved a problem in a professional setting (detail the situation, constraints, your actions, measurable outcome, and reflect on decision-making and lessons).", "limit": "500 words, double-spaced, 12-pt", "required": true}], "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "video_assessment": {"value": "Video essay required on an online platform; questions on goals, experience and fit, not shared in advance.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "interview": {"value": "Finalists get a 30-minute video interview with an Admissions Committee member; no in-person interviews; decision within 2-3 weeks.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "recommendations": {"value": "One professional letter required (current/former manager); second optional. Professional email address required.", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "other_requirements": {"value": "Resume max 2 pages; seeks minimum 2-3 years of digital/tech-related experience; class average 5 years work experience; transcripts from all universities (official not needed at application).", "source_url": "https://tech.cornell.edu/admissions/mba-application/"}, "notes": "Indonesian applicants: non-US/Canada transcripts need a course-by-course evaluation by an approved US evaluator (ECE, IEE, Scholaro, SpanTran, WES or NACES member), paid by applicant, required before the committee reviews the application. International students were 74% of Class of 2026. I-20 needs proof of funding and deposit (Cornell Tech admitted-student page). Separate from other Johnson MBA applications."}'::jsonb,'{"class_label": "Class of 2026", "gmat_avg": 675, "gmat_median": null, "gmat_range": "middle 80%: 590-730 (edition not stated on page)", "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": 157, "gre_quant_avg": 163, "gre_range": "V 150-164, Q 156-169 (middle 80%)", "gpa_avg": 3.53, "gpa_range": "middle 80%: 3.12-3.86", "work_exp_avg_years": 5, "work_exp_range": "middle 80%: 4-8 years", "class_size": 74, "international_pct": 74, "women_pct": 39, "countries": 19, "pct_submitted_gre": null, "source_url": "https://www.tech.cornell.edu/admissions/mba-application/", "source_name": "Cornell Tech MBA application page (class profile shown is Class of 2026; no newer profile found)"}'::jsonb,'{"report_label": "Johnson Cornell Tech MBA Class of 2025 (n=95; 66% job seekers, 17% founders, 17% other paths)", "employed_3_months_pct": null, "median_base_salary": "USD 170,000", "mean_base_salary": null, "top_industries": "No percentages; mostly technology (mature companies and startups)", "top_employers": "Amazon, ByteDance, Capital One, Netflix, McKinsey, Oliver Wyman, Uber, UBS, Upwork, Taskrabbit, Fiserv, others (unranked)", "international_employed_note": "64% employed 9 months after graduation (page gives no 3 or 6 month figure); 66% of job seekers employed within 9 months. Locations: 60% NYC, 36% elsewhere US, 5% international. STEM-designated; international students who return home counted under other paths. Equity is a large part of pay so base is lower.", "source_url": "https://tech.cornell.edu/career-management/career-outcomes", "source_name": "Cornell Tech career outcomes page"}'::jsonb),
