('Cornell Johnson','M.S. in Hotel Administration (research master''s)','masters','full-time',null,'Fall','https://business.cornell.edu/admissions/graduate/ms-hotel-admin/','{"deadlines": {"value": "Application period September 1 to December 15 for fall admission (page text covers both programs). Year not stated.", "source_url": "https://business.cornell.edu/admissions/graduate/ms-hotel-admin/"}, "application_fee": {"value": "USD 105, nonrefundable, paid by card with the online application (Cornell Graduate School). Waivers only in limited cases (e.g. FAFSA filers, fully funded doctoral/research master''s applicants, hardship).", "source_url": "https://gradschool.cornell.edu/admissions/application-steps/pay-fees/"}, "tests": {"value": "GMAT or GRE score required (GMAT code 5811, GRE code 2098). Page lists a score above 700 as a trait of competitive applicants; no stated minimum.", "source_url": "https://business.cornell.edu/admissions/graduate/ms-hotel-admin/how-to-apply/"}, "english": {"ielts_min": "7.0 overall (IELTS Academic)", "toefl_min": "100 iBT (per Hotel Administration field-of-study page); Graduate School general TOEFL section minimums also apply, 2026-27 interim scale", "duolingo": "not accepted", "pte_min": "not accepted", "other_tests": null, "waiver": "Graduate School standing exemptions: first-language English speaker who is citizen/PR of an English-official country; US bachelor''s degree from accredited US institution; bachelor''s equivalent from English-official country taught in English; or 2 consecutive years full-time study/work in an English-official country within last 10 years. Only IELTS Academic and TOEFL iBT accepted by Graduate School.", "source_url": "https://gradschool.cornell.edu/academics/fields-of-study/subject/hotel-administration-m-m-h-administered-by-the-johnson-school/hotel-administration-ms-ithaca/"}, "essays": {"items": [{"prompt": "Personal Statement: describe how your background and experiences led you to pursue a graduate degree, and how you would contribute to Cornell''s community of inclusion, belonging, and respect.", "limit": "not stated", "required": true}, {"prompt": "Academic Statement of Purpose (guidance linked from page)", "limit": "not stated", "required": true}], "source_url": "https://business.cornell.edu/admissions/graduate/ms-hotel-admin/how-to-apply/"}, "video_assessment": null, "interview": {"value": "Admissions Committee invites the strongest candidates for personal interviews with graduate faculty.", "source_url": "https://business.cornell.edu/admissions/graduate/ms-hotel-admin/how-to-apply/"}, "recommendations": {"value": "At least two original letters: one from a college-level academic instructor and one from an employer or professional reference.", "source_url": "https://business.cornell.edu/admissions/graduate/ms-hotel-admin/how-to-apply/"}, "other_requirements": null, "notes": "Page only gave deadlines and a profile; requirements are on a separate ''How to apply to the M.S.'' page not fetched. Research-focused with thesis and final exam."}'::jsonb,null,null),
('Duke Fuqua','Daytime MBA','mba','full-time','22 months','2026-27 application cycle (entry term not stated on fetched pages)','https://www.fuqua.duke.edu/programs/daytime-mba','{"deadlines": {"value": "2026-27 cycle. Early Action (binding): app Sep 2, 2026, final decision Oct 15, 2026. Round 1: Sep 30, 2026 (decision Dec 10). Round 2: Jan 5, 2027 (decision Mar 11). Round 3: Mar 25, 2027 (decision May 6). Consortium deadlines Oct 15 and Jan 5. International applicants advised to apply EA, R1 or R2.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/admissions-facts-dates"}, "application_fee": {"value": "USD 225, non-refundable. USD 75 discount for qualifying events/endorsements; full waivers for categories incl. Duke alumni, military, Early Action applicants, reapplicants (select option in application).", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "tests": {"value": "GMAT, GMAT Focus, GRE and Executive Assessment accepted; no minimum score. Valid 5 years; self-report at application, official scores if admitted. Committee pays particular attention to quantitative section. No waiver policy stated on the page.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not accepted", "pte_min": null, "other_tests": null, "waiver": "Fuqua does not accept ESL test scores such as TOEFL, IELTS, PTE or Duolingo; proficiency assessed through essays, resume, recommendation and, if invited, a 45-60 minute English-language interview. No waiver concept applies. ESL scores required only for MBA/MEM dual degree (MEM application).", "source_url": "https://www.fuqua.duke.edu/mba-english-proficiency-requirements"}, "essays": {"items": [{"prompt": "What are your post-MBA career goals? (share a first-choice plan and an alternate plan)", "limit": "100 words", "required": true}, {"prompt": "Please share with us ''25 Random Things'' about you. (numbered list 1 to 25)", "limit": "750 words max, about 2 pages", "required": true}, {"prompt": "The Fuqua Community and You: describe three ways you expect to contribute to Fuqua, based on your understanding of its culture.", "limit": "500 words, 1 page", "required": true}, {"prompt": "Optional essay: explain circumstances the committee should know (employment gaps, recommender choice, academic inconsistencies).", "limit": "500 words, 1 page", "required": false}, {"prompt": "Reapplicant essay: reflect on your growth since your last application.", "limit": "500 words, 1 page", "required": false}], "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "video_assessment": {"value": "No video essay or video assessment mentioned in the Daytime MBA application instructions; interviews by invitation, conducted in English.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "interview": {"value": "By invitation only, in person or virtually; assesses interpersonal skills and fit. Early Action: interview decision by Sep 23, 2026.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/admissions-facts-dates"}, "recommendations": {"value": "One recommendation required (new applicants), via online form only; recent professional setting; relatives/friends discouraged; academic recommenders less helpful. Optional alumni/student endorsement.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "other_requirements": {"value": "One-page resume; unofficial transcripts for each degree institution; bachelor''s degree from accredited institution before start; official transcripts after admission. No minimum work experience.", "source_url": "https://www.fuqua.duke.edu/programs/daytime-mba/application-instructions"}, "notes": "Fuqua does not accept ESL test scores (no TOEIC/TOEFL/IELTS score route stated). Non-English documents need translation + attestation; 3-year degrees accepted if US-equivalent. Apply by Round 3 at the latest for visa processing, ideally EA/R1/R2. Page lists no video essay. Optional essay limit differs by page (500 words here)."}'::jsonb,'{"class_label": "Class of 2028 (entering fall 2026)", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "middle 80%: 605-715 (GMAT Focus)", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "combined V+Q middle 80%: 307-330; Executive Assessment middle 80%: 150-162", "gpa_avg": null, "gpa_range": "undergrad middle 80%: 3.15-3.90", "work_exp_avg_years": 6.0, "work_exp_range": "middle 80%: 3.17-9.50 years", "class_size": 359, "international_pct": 38, "women_pct": 44, "countries": 46, "pct_submitted_gre": null, "source_url": "https://fuqua.duke.edu/programs/daytime-mba/class-profile", "source_name": "Fuqua Daytime MBA class profile page (countries=46 from Clear Admit''s Class of 2028 article; official page did not list it)"}'::jsonb,'{"report_label": "Class of 2025 Daytime MBA employment report (350 graduates, 315 seeking)", "employed_3_months_pct": 79, "median_base_salary": "USD 160,000", "mean_base_salary": null, "top_industries": "Consulting 34.0%, Financial Services 20.9%, Technology 15.6%, Healthcare 7.4%", "top_employers": "106 employers hired 3+ (unranked), incl. Amazon, Bain, BCG, Goldman Sachs, JPMorgan Chase, McKinsey, Microsoft, Morgan Stanley, PwC", "international_employed_note": "79% accepted by 3 months (82.2% had an offer). Report gives no breakdown by visa/work authorization; offers without work authorization counted in totals but not in breakdowns. Median signing bonus USD 30,000.", "source_url": "https://www.fuqua.duke.edu/sites/default/files/media/programs/daytime/duke-mba-employment-2025.pdf", "source_name": "Fuqua Daytime MBA Employment Report 2025 PDF"}'::jsonb),
('Duke Fuqua','Accelerated Daytime MBA','mba','full-time','10 months','2026-27 application cycle (entry term not stated on fetched pages)','https://www.fuqua.duke.edu/programs/accelerated-daytime-mba','{"deadlines": {"value": "2026-27 cycle. Round 1: Sep 23, 2026 (decision Dec 10). Round 2: Jan 5, 2027 (decision Mar 11). Round 3: Mar 18, 2027 (decision May 6). No Early Action; international applicants should apply R1 or R2.", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/admissions-facts-dates"}, "application_fee": {"value": "USD 225, non-refundable; USD 75 discount and some full waivers (select option in application).", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/application-instructions"}, "tests": {"value": "GMAT, GRE or Executive Assessment; no preference, no minimum; valid 5 years; self-report, official if admitted. Committee focuses on quantitative segment.", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/application-instructions"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not accepted", "pte_min": null, "other_tests": null, "waiver": "Fuqua does not accept ESL test scores (TOEFL, IELTS, PTE, Duolingo); language proficiency is assessed from other parts of the application. Transcripts, diplomas and academic records must be in English.", "source_url": "https://www.fuqua.duke.edu/node/4480"}, "essays": {"items": [{"prompt": "What are your post-MBA career goals? (first-choice plan and alternate plan)", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "25 Random Things: numbered list 1 to 25 about yourself, beyond resume and transcript.", "limit": "750 words max, ~2 pages", "required": true}, {"prompt": "Fuqua community essay: describe three ways you expect to contribute to Fuqua, based on your understanding of its culture.", "limit": "500 words, 1 page", "required": true}, {"prompt": "Optional essay: explain circumstances the committee should know about.", "limit": "300 words, 1 page", "required": false}, {"prompt": "Reapplicant essay: reflect on growth since last application.", "limit": "500 words, 1 page", "required": false}], "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/application-instructions"}, "video_assessment": {"value": "No video essay or recorded video assessment mentioned; application has one short-answer question and two essays plus optional essay. Interviews by invitation (campus or video conference), conducted in English.", "source_url": "https://www.fuqua.duke.edu/node/4480"}, "interview": {"value": "By invitation only, in person or virtually.", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/admissions-facts-dates"}, "recommendations": {"value": "One recommendation required via online form; recent professional recommender preferred; optional endorsement.", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/application-instructions"}, "other_requirements": {"value": "Prior degree required: Fuqua MMS, MiM or equivalent from accredited graduate business school, Fuqua MQM, or MS Business Analytics or equivalent, with specified core coursework. Two-year MBA graduates, PGDM holders and certificate holders (CFA, PMP) do not qualify. Strongly prefer 2+ years business experience after the master''s. One-page resume.", "source_url": "https://www.fuqua.duke.edu/programs/accelerated-daytime-mba/admissions-facts-dates"}, "notes": "Only open to people already holding a business/quant master''s from the eligible list; not an entry route from a bachelor''s. Fuqua does not accept ESL test scores."}'::jsonb,null,null),
('Duke Fuqua','Master of Management Studies (Duke MMS)','masters','full-time','10 months','2026-27 application cycle (entry term not stated)','https://www.fuqua.duke.edu/programs/duke-mms','{"deadlines": {"value": "2026-27 cycle. Round 1: Oct 7, 2026 (decision Dec 9). Round 2: Jan 13, 2027 (decision Mar 9). Round 3: Mar 4, 2027 (decision Apr 23). Round 4: Apr 13, 2027 (decision May 21). International applicants: apply R1 or R2.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/admissions-facts-dates"}, "application_fee": {"value": "USD 125, non-refundable; USD 75 discount for qualifying activities; full waiver for listed groups and for submitting a Duolingo English Test score.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "tests": {"value": "GMAT, GRE, SAT or ACT: one score required for a complete application. GMAT/GRE valid 5 yrs; SAT/ACT valid 10 yrs. Waiver possible with cumulative undergrad GPA 3.4+ on 4.0 scale plus quantitative coursework; request at least 2 weeks before round deadline, discretionary, no appeal. No minimum score stated.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "english": {"ielts_min": "IELTS Academic: 7.0 minimum (7.5+ preferred)", "toefl_min": "TOEFL iBT 0-120 scale: 95 minimum (105+ preferred); new 1-6 scale: 5 minimum (5.5+ preferred)", "duolingo": "accepted (min 125; 135+ preferred; listed as the preferred test)", "pte_min": null, "other_tests": "PTE not mentioned on page. Scores no more than 2 years old; unofficial accepted at application, official after admission.", "waiver": "Required if first language is not English unless an approved exemption applies (criteria not listed). Exceptional-proficiency waiver can be requested after starting application; documentation and/or video may be required.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "essays": {"items": [{"prompt": "Why are you pursuing the MMS degree at this stage in your professional development?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "What are your immediate career goals after completing the MMS program?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "Should the immediate goals that you provided above not materialize, what alternative directions have you considered?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "Please present your response in list form, numbered 1 to 25 (''25 Random Things'').", "limit": "max 2 pages", "required": true}, {"prompt": "Essay 2 (350 words max): Starts ''The strength of the Fuqua community comes from the everyday interactions among its students.'' then asks what strengths/perspectives you will bring, what you hope to learn, and how these interactions shape your growth (full wording on source page).", "limit": "350 words", "required": true}, {"prompt": "Optional essay: explain circumstances the committee should know about (work gaps, non-professional recommender, academic inconsistencies). Do not upload additional essays or recommendations.", "limit": "no limit stated (one page)", "required": false}, {"prompt": "Reapplicant essay: reflect on growth since last application.", "limit": "max 2 pages", "required": false}], "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "video_assessment": {"value": "No standard application video. Video submission may be requested only in an English-proficiency waiver review.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "interview": {"value": "By invitation only after application review; no open interviews. Mostly video conference; NC (and SC/VA on some pages) residents may be invited on campus; equal weight. Interviewers are staff, alumni or select second-year MBA students; ~30-45 min in English.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/admissions-facts-dates"}, "recommendations": {"value": "One letter required, from someone who knows you professionally (supervisor); academic recommender allowed only if no professional one, explain in Optional Essay. Only one recommendation may be submitted; use work email; relatives/friends discouraged.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/application-instructions"}, "other_requirements": {"value": "One-page resume; unofficial transcripts; official transcripts with degree conferred by June 25. No minimum work experience; ~2 years or less full-time post-grad experience recommended. Strong quantitative preparation expected. May apply to only one of Duke MMS or MMS: Duke Kunshan per year.", "source_url": "https://www.fuqua.duke.edu/programs/duke-mms/admissions-facts-dates"}, "notes": "Round 1 or 2 advised for F-1 visa processing; visa web form must be received at least 6 weeks before start (visa dates printed on some pages are from prior cycles, confirm). Visa process starts after tuition deposit. 3-year bachelor''s accepted if equivalent to US degree. Transcripts/diplomas must be in English: translated, attested copies uploaded with originals (WES English transcript acceptable per MBA page). If transcript lacks degree/conferral date, upload diploma. Official transcripts only after admission (transcripts@fuqua.duke.edu). Submitting Duolingo waives the application fee."}'::jsonb,'{"class_label": "Class of 2027", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "middle 80%: 535-645 (GMAT Focus)", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "V 150-168, Q 162-170 (middle 80%)", "gpa_avg": 3.38, "gpa_range": null, "work_exp_avg_years": 1.25, "work_exp_range": "avg 15 months; 12% of students have work experience", "class_size": 34, "international_pct": null, "women_pct": 41, "countries": 6, "pct_submitted_gre": null, "source_url": "https://www.fuqua.duke.edu/programs/mms-duke-kunshan-university/class-profile", "source_name": "Fuqua MMS:DKU class profile page (average age 23)"}'::jsonb,'{"report_label": "MMS:DKU Class of 2025 employment report", "employed_3_months_pct": null, "median_base_salary": "USD 30,085 (RMB 211,200; n=32)", "mean_base_salary": "USD 33,793 (RMB 237,230)", "top_industries": "Finance 34%, Technology 26%, Energy 13%", "top_employers": "China Sinopec (3), JD.com (2), Xiaomi (2); also Baowu, CITIC Securities, China Merchants Bank, ICBC, Midea, PwC", "international_employed_note": "No 3-month figure; 93% of seekers accepted offers within 6 months, 37% by graduation. 81% of jobs in Chinese mainland/HK/Taiwan, 5% in US.", "source_url": "https://www.fuqua.duke.edu/sites/default/files/media/programs/mmsdku/2025%20DKU%20Employment%20Report_FINAL.pdf", "source_name": "Fuqua 2025 DKU Employment Report PDF"}'::jsonb),
