ctions"}, "essays": {"items": [{"prompt": "Why are you pursuing the MMS degree at this stage in your professional development?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "What are your immediate career goals after completing the MMS program?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "Should the immediate goals that you provided above not materialize, what alternative directions have you considered?", "limit": "500 characters (~100 words)", "required": true}, {"prompt": "Please present your response in list form, numbered 1 to 25 (''25 Random Things'').", "limit": "max 2 pages", "required": true}, {"prompt": "Essay 2 (350 words max): Starts ''The strength of the Fuqua community comes from the everyday interactions among its students.'' then asks what strengths/perspectives you will bring, what you hope to learn, and how these interactions shape your growth (full wording on source page).", "limit": "350 words", "required": true}, {"prompt": "Optional essay: explain circumstances the committee should know about (work gaps, non-professional recommender, academic inconsistencies). Do not upload additional essays or recommendations.", "limit": "no limit stated (one page)", "required": false}, {"prompt": "Reapplicant essay: reflect on growth since last application.", "limit": "max 2 pages", "required": false}], "source_url": "https://www.fuqua.duke.edu/programs/mms-duke-kunshan-university/application-instructions"}, "video_assessment": {"value": "No standard application video; may be requested for English-waiver review.", "source_url": "https://www.fuqua.duke.edu/programs/mms-duke-kunshan-university/application-instructions"}, "interview": {"value": "By invitation only after application review; no open interviews. Mostly video conference; NC (and SC/VA on some pages) residents may be invited on campus; equal weight. Interviewers are staff, alumni or select second-year MBA students; ~30-45 min in English.", "source_