, "essays": {"items": [{"prompt": "Why did you select your preferred track(s): Finance, Marketing, Risk, or Strategy?", "limit": "750 characters", "required": true}, {"prompt": "What are your immediate career goals after completing the program?", "limit": "750 characters", "required": true}, {"prompt": "Please present your response in list form, numbered 1 to 25 (''25 Random Things'').", "limit": "max 2 pages", "required": true}, {"prompt": "Essay 2 (350 words max): Starts ''The strength of the Fuqua community comes from the everyday interactions among its students.'' then asks what strengths/perspectives you will bring, what you hope to learn, and how these interactions shape your growth (full wording on source page).", "limit": "350 words", "required": true}, {"prompt": "Optional essay: explain circumstances the committee should know about (work gaps, non-professional recommender, academic inconsistencies). Do not upload additional essays or recommendations.", "limit": "no limit stated (one page)", "required": false}, {"prompt": "Reapplicant essay: reflect on growth since last application.", "limit": "max 2 pages", "required": false}], "source_url": "https://www.fuqua.duke.edu/programs/mqm-business-analytics/application-instructions"}, "video_assessment": {"value": "No standard application video; video may be requested only for English-waiver review.", "source_url": "https://www.fuqua.duke.edu/programs/mqm-business-analytics/application-instructions"}, "interview": {"value": "By invitation only after application review; no open interviews. Mostly video conference; NC (and SC/VA on some pages) residents may be invited on campus; equal weight. Interviewers are staff, alumni or select second-year MBA students; ~30-45 min in English.", "source_url": "https://www.fuqua.duke.edu/programs/mqm-business-analytics/admissions-facts-dates"}, "recommendations": {"value": "One letter required, from someone who knows you professionally (supervisor); academic recommender allowed only if no professional one, explain in Optional Essay. Only one recommendation may be submitted; use work email; relatives/friends discouraged.", "source_url": "https://www.fuqua.duke.edu/programs/mqm-business-analytics/application-instructions"}, "other_requirements": {"value": "Current one-page resume; unofficial transcripts; 4-year degree in STEM, business, economics or equivalent quantitative major preferred; strong math/stats/CS coursework expected; no work experience required, no more than 3 years full-time post-grad recommended.", "source_url": "https://www.fuqua.duke.edu/programs/mqm-business-analytics/admissions-facts-dates"}, "notes": "Round 1 or 2 advised for F-1 visa processing; visa web form must be received at least 6 weeks before start (visa dates printed on some pages are from prior cycles, confirm). Visa process starts after tuition deposit. 3-year bachelor''s accepted if equivalent to US degree. Transcripts/diplomas must be in English: translated, attested copies uploaded with originals (WES English transcript acceptable per MBA page). If transcript lacks degree/conferral date, upload diploma. Official transcripts only after admission (transcripts@fuqua.duke.edu)."}'::jsonb,'{"class_label": "Class of 2027", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "middle 80%: 475-685 (GMAT Focus)", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "V 150-166, Q 162-170 (middle 80%)", "gpa_avg": 3.57, "gpa_range": null, "work_exp_avg_years": 1.67, "work_exp_range": "avg 20 months; 26% of students have work experience", "class_size": 150, "international_pct": null, "women_pct": 47, "countries": 17, "pct_submitted_gre": null, "source_url": "https://fuqua.duke.edu/programs/master-quantitative-management/class-profile", "source_name": "Fuqua MQM class profile page (average age 23; international % not stated)"}'::jsonb,'{"report_label": "Class of 2025 MQM: Business Analytics employment report (2