: 5.67, "work_exp_range": null, "class_size": 361, "international_pct": 30, "women_pct": 35, "countries": 28, "pct_submitted_gre": null, "source_url": "https://www.darden.virginia.edu/programs/blog/introducing-uva-dardens-full-time-mba-class-of-2027-class-profile", "source_name": "UVA Darden admissions blog, Class of 2027 profile"}'::jsonb,'{"report_label": "Class of 2025 Full-Time MBA employment outcome data (327 of 352 seeking)", "employed_3_months_pct": 89.3, "median_base_salary": "USD 175,000", "mean_base_salary": "USD 162,578", "top_industries": "Consulting 37.3%, Financial Services 26.0%, Technology 16.1%, CPG 3.8%, Healthcare 3.1%, Retail 3.1%", "top_employers": "Not named in the PDF", "international_employed_note": "Accepted by 3 months: 90.9% permanent work authorization (180/198) vs 86.8% non-permanent (112/129); median base USD 175,000 for both. 98.3% of accepting graduates took North America jobs. 89.3% is 292/327 (counts stated, % derived from counts on the page).", "source_url": "https://www.darden.virginia.edu/sites/default/files/2025-11/UVA%20Darden%20Class%20of%202025%20FT%20Employment%20Outcome%20Data_web.pdf", "source_name": "UVA Darden Class of 2025 FT Employment Outcome Data PDF"}'::jsonb),
('UVA Darden','Part-Time MBA (DC Metro)','mba','hybrid','24-48 months, flexible','Aug 2027 (all rounds target August start of following calendar year)','https://www.darden.virginia.edu/part-time-mba','{"deadlines": {"value": "2026-27 cycle, monthly rounds (decision date): Sep 1, 2026 (Sep 25); Oct 1 (Oct 23); Nov 1 (Nov 20); Dec 1 (Dec 18); Feb 1, 2027 (Feb 26); Mar 1 (Mar 26); Apr 1 (Apr 23); May 1 (May 21); Jun 1 (Jun 18); Jun 15 (Jun 25); Jul 2 (Jul 16). Page also says the cycle is ''currently closed'', confirm with ptmba@darden.virginia.edu.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process/deadlines"}, "application_fee": {"value": "USD 250, non-refundable; waived via phone conversation with committee, webinar/event attendance, or eligible groups (veterans, first-gen, UVA/Virginia alumni, etc.).", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "tests": {"value": "Not required. GMAT, GRE, EA, MCAT or LSAT accepted and viewed equivalently; old/expired scores accepted with full breakdown.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "english": {"ielts_min": "No minimum score", "toefl_min": "No minimum; average TOEFL 106", "duolingo": "not stated", "pte_min": "Accepted; no minimum stated", "other_tests": "TOEFL, IELTS and PTE accepted; TOEFL valid 2 years; TOEFL code 5820 Dept 02; IELTS 5099.", "waiver": "Not required if bachelor''s from English-medium university; strongly recommended if bachelor''s non-English but master''s/PhD English-medium; required otherwise.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "essays": {"items": [], "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "video_assessment": {"value": "None listed. Application Process page lists form, transcripts, optional test, resume, recommendation, short-answer questions, fee and invitation-only Zoom interview; no video essay (the 2026-27 Full-Time MBA has a new 90-second video essay, but that is not listed for Part-Time).", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "interview": {"value": "Required, invitation-only, virtual via Zoom with an Admissions Committee member, typically 35-40 minutes.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "recommendations": {"value": "One required, two accepted; current supervisor preferred; ratings grid plus three short-answer questions.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "other_requirements": {"value": "Resume; unofficial transcripts for all degree coursework (official before matriculation); no minimum work experience stated. USD 4,000 deposit if admitted.", "source_url": "https://www.darden.virginia.edu/part-time-mba/admissions/application-process"}, "notes": "Essay prompts: page says multiple short-answer questions are required but does not list them. Non-English records need complete literal translation. Part-time, mostly evening in Arlington VA: check whether it supports an F-1 student visa (not stated on fetched pages)."}'::jsonb,null,null),
('UVA Darden','M.S. in Business Analytics (MSBA)','masters','hybrid','12 months','Fall 2027 (MSBA Class of 2028)','https://msba.virginia.edu/','{"deadlines": {"value": "Fall 2027 entry. R1: Nov 5, 2026 (decision Dec 11). R2: Jan 5, 2027 (Feb 5). R3: Mar 5 (Apr 9). R4: May 5 (Jun 4). R5: Jun 5, 2027. R6 (final): Jul 15, 2027; later rounds space-available rolling. Deposits USD 1,000 + 1,500.", "source_url": "https://msba.virginia.edu/admissions/deadlines/"}, "application_fee": {"value": "USD 85", "source_url": "https://msba.virginia.edu/admissions/application-process/"}, "tests": {"value": "GMAT, GRE or EA optional (test scores optional).", "source_url": "https://msba.virginia.edu/admissions/requirements/"}, "english": {"ielts_min": "7.5 overall", "toefl_min": "100 iBT (old 0-120 scale) or 5.5 (new 1-6 scale)", "duolingo": "not stated", "pte_min": null, "other_tests": "Page names only TOEFL and IELTS; committee may request additional evidence.", "waiver": "Native non-English speakers exempt if they completed an undergraduate degree at a regionally accredited US institution with at least 2 years full-time in residence.", "source_url": "https://msba.virginia.edu/admissions/international-applicants/"}, "essays": {"items": [], "source_url": "https://msba.virginia.edu/admissions/application-process/"}, "video_assessment": null, "interview": {"value": "By invitation only after preliminary review; complete within one week of invitation; decisions within two weeks after.", "source_url": "https://msba.virginia.edu/admissions/application-process/"}, "recommendations": {"value": "One letter of recommendation.", "source_url": "https://msba.virginia.edu/admissions/application-process/"}, "other_requirements": {"value": "Conferred bachelor''s from regionally accredited institution; minimum 2 years professional work experience by first day of class; unofficial transcripts or transcript evaluations for application.", "source_url": "https://msba.virginia.edu/admissions/requirements/"}, "notes": "Page says two required essays but gives no prompts. Program cannot provide F-1 visa sponsorship (non-residential); do not expect an I-20. Non-US transcripts must be evaluated by a NACES service with calculated GPA; photocopies and notarized copies not accepted as official. English page wording refers to McIntire, confirm minimums with admissions."}'::jsonb,null,'{"report_label": "MSBA Class of 2026 career outcomes", "employed_3_months_pct": null, "median_base_salary": "By function only: Business/Data Analytics median USD 109,000; Consulting 167,500; Finance 113,000", "mean_base_salary": null, "top_industries": "Government/Military 32%, Financial Services 21%, Consulting 16%, Technology 11%, Nonprofit/Education 8%", "top_employers": "Booz Allen Hamilton, Deloitte, EY, Morgan Stanley, Citadel Securities, Marriott, Dominion Energy, DoD, US Navy, SAIC, others (unranked)", "international_employed_note": "No international outcome data on page; no overall employment rate or overall median stated.", "source_url": "https://msba.virginia.edu/career-network/career-outcomes/", "source_name": "UVA MSBA career outcomes page"}'::jsonb),
('INSEAD','INSEAD MBA','mba','full-time','1 year (about 10 months)','August 2027 and January 2028 (Singapore or Fontainebleau)','https://www.insead.edu/master-programmes/master-business-administration','{"deadlines": {"value": "Aug 2027 intake: R1 15 Sep 2026; R2 03 Nov 2026; R3 19 Jan 2027; R4 09 Mar 2027. Jan 2028 intake: R1 23 Mar 2027; R2 27 Apr 2027; R3 29 Jun 2027; R4 03 Aug 2027. Interview decisions about one month after each deadline.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "application_fee": {"value": "EUR 250, non-refundable, paid online by credit card", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "tests": {"value": "GMAT or GRE required; take any time up to the deadline; scores sent directly to INSEAD, valid 5 years. No minimum or waiver stated on the page.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "accepted (DET listed as accepted test; minimum not stated on fetched pages)", "pte_min": null, "other_tests": null, "waiver": "University degree taught entirely in English (full academic year, transcripts must show it) or one-year English-taught exchange; living/working in an English-speaking country and English majors do not count. Tests valid 2 years. Committee may still require a test.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/faqs"}, "essays": {"items": [{"prompt": "Job description essay 1: Summarise your career since university, explaining key decisions and progression, and describe your current or most recent role.", "limit": "500 words", "required": true}, {"prompt": "Job description essay 2: Describe your short- and long-term career aspirations (geography, industry, function), how you will bridge the gap, and how INSEAD will help.", "limit": "300 words", "required": true}, {"prompt": "Motivation essay 1: Give a candid description of yourself as a person and leader, covering strengths, weaknesses, and how you are working on your development.", "limit": "500 words", "required": true}, {"prompt": "Motivation essay 2: Describe a highly stressful situation, how you managed it, and what it taught you about yourself and your interactions with others.", "limit": "400 words", "required": true}, {"prompt": "Motivation essay 3: Is there anything else that was not covered in your application?", "limit": "300 words", "required": true}], "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "video_assessment": {"value": "Kira Talent link sent after submission; complete within 48 hours of the application deadline. 4 video questions (45s prep, 60s answer each) plus 1 written question (5 minutes); about 15-20 minutes.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "interview": {"value": "Pre-selected candidates interview with two INSEAD alumni, typically in country of residence; feedback goes to Admissions Committee. Full process up to 10 weeks.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "recommendations": {"value": "2 required by the deadline; professional (manager/client/colleague) strongly recommended, academic accepted. Optional third.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "other_requirements": {"value": "CV (free format or INSEAD CV Book template); scanned transcripts and diploma at application, official documents if admitted; typical class 3-8 years experience (range 2-10); campus choice France/Singapore.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/admissions"}, "notes": "MBA Language Policy PDF (oct-2026) holds minimum scores and second-language rules but was blocked to fetch. Non-European applicants: apply early for French student visa (cannot apply more than 6 months before departure). Deferrals generally not granted. Fee EUR 109,860 and scholarships listed on program page."}'::jsonb,'{"class_label": "Typical MBA class (no cohort year stated; avg age 29, range 23-35)", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": null, "work_exp_range": "Average 3-8 years; range 2-10 years (as stated on page)", "class_size": null, "international_pct": null, "women_pct": 38, "countries": 75, "pct_submitted_gre": null, "source_url": "https://insead.edu/mba", "source_name": "INSEAD MBA page, Typical MBA Class (class size 900-950 across two intakes; about 90 nationalities; no GMAT on page)"}'::jsonb,'{"report_label": "Class of 2025 MBA employment statistics (929 graduates, Dec 2024 and Jul 2025; 98% response, 73% reported full salary)", "employed_3_months_pct": 81, "median_base_salary": "EUR 100,000", "mean_base_salary": "EUR 102,200", "top_industries": "Management Consulting 50%, TMT 18%, Corporate Sectors 17%, Financial Services 15%", "top_employers": "McKinsey, BCG, Bain, Strategy&, Accenture, Kearney, Amazon, Oliver Wyman, FTI Consulting, Dell", "international_employed_note": "81% = at least one job offer within 3 months. Jobs in 57 countries; 34% changed country; North America only 6% of locations. Page says nothing on visas.", "source_url": "https://www.insead.edu/master-programmes/master-business-administration/employment-statistics", "source_name": "INSEAD MBA Employment Statistics"}'::jsonb),
