('London Business School','MBA','mba','full-time','15 to 21 months (exit at 15, 18 or 21 months)','August 2027 (starts 9 August 2027)','https://www.london.edu/masters-degrees/mba','{"deadlines": {"value": "Three application deadlines a year, all 17:00 UK time. Calendar with exact round dates sits in the ''Application calendar'' section and was not in the fetched page text. Applications for August 2027 intake open.", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "application_fee": {"value": "GBP 200 (waived for LBS alumni and active military)", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "tests": {"value": "GMAT or GRE required by round deadline; scores under 5 years old; no preference between them. Average GMAT about 645 (range 555-805), minimum usually about 555; for GRE prefers over 160 on verbal and quant. May ask for a retake. No waiver listed.", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "english": {"ielts_min": "7.0 overall, 6.5 each band", "toefl_min": "100 iBT (min 20 Listening, 20 Speaking, 19 Reading, 24 Writing)", "duolingo": "accepted (min 135 overall, 125 each component)", "pte_min": "76 overall, 70 each component", "other_tests": "Cambridge CAE/CPE 180 overall, 170 each", "waiver": "Majority English-speaking country native-national exempt. At Committee discretion: 2+ years professional work in a majority English-speaking country, or full-time degree taught entirely in English in such a country completed within 5 years of start (exchange years do not count). Tests within 2 years of August start.", "source_url": "https://assets.london.edu/hxo16fanegqh/3lQVKRZT5VLn2F1d7XDQNw/f2a0666f4c87e99e8fc2958f7bbd7576/English_Language_Info_Sheet.pdf"}, "essays": {"items": [{"prompt": "Post-MBA goals and how your prior experience and the LBS programme will help (page wording paraphrased: ''What are your post-MBA goals and how will your prior experience...'')", "limit": "500 words", "required": true}, {"prompt": "What makes you unique?", "limit": "200 words", "required": true}, {"prompt": "Optional: any other information the Admissions Committee should know", "limit": "500 words", "required": false}], "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "video_assessment": {"value": "No video assessment listed. Application page lists three essays, one-page CV, a referee, GMAT/GRE and fee; no video submission mentioned. (Absence-based.)", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "interview": {"value": "Selected applicants interviewed by alumni or senior admissions staff, usually in their region; may need to travel. FAQ says interviews and video submissions must be done without AI or outside help.", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "recommendations": {"value": "1 professional referee (current employer, colleague, or someone who knows your work well)", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "other_requirements": {"value": "One-page CV; transcripts from every university (certified English translation if needed; originals if offered); average work experience about 5.5 years, under 3 years possible with strong academics and leadership; UK study visa needed after offer.", "source_url": "https://www.london.edu/masters-degrees/mba/apply"}, "notes": "No video assessment mentioned on the apply page. Essay 1 prompt text is paraphrased from the page extraction; verify exact wording. AI may be used for essay editing only if disclosed. Calendar dates not captured."}'::jsonb,'{"class_label": "MBA2027 (class profile page)", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 5.5, "work_exp_range": null, "class_size": 514, "international_pct": 90, "women_pct": 44, "countries": 66, "pct_submitted_gre