('London Business School','One-year MBA (for experienced masters graduates)','mba','full-time','11 months','August 2027 (listed 9 August 2027; page labels conflict)','https://www.london.edu/masters-degrees/one-year-mba','{"deadlines": {"value": "Five application deadlines per year, all 17:00 UK time. Calendar with exact round dates sits in the ''Application calendar'' section and was not in the fetched page text. ", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "application_fee": {"value": "GBP 200 (waived for LBS alumni and active military)", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "tests": {"value": "Valid GMAT, GRE or EA before submitting; under 5 years old. Average GMAT about 645 (555-805), minimum usually about 555; EA around 150 preferred. Possible to apply without a score by emailing admissions first, but test needed before offer.", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "accepted (score not stated on this page)", "pte_min": null, "other_tests": null, "waiver": "Required unless first language English and always citizen/resident of a majority English-speaking country. Committee may waive. (Score minimums on the MBA info sheet cover the MBA only.)", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "essays": {"items": [{"prompt": "What are your post-MBA goals and how will your prior experience and the LBS programme contribute to them?", "limit": "500 words", "required": true}, {"prompt": "What makes you unique?", "limit": "200 words", "required": true}, {"prompt": "Optional: any other information the Admissions Committee should know", "limit": "500 words", "required": false}], "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "video_assessment": {"value": "No video assessment listed on the apply page (essays, interview with alumni/senior admissions staff). Absence-based.", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "interview": {"value": "Selected applicants interviewed by One-year MBA alumni or senior admissions staff in their region; may need to travel.", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "recommendations": {"value": "1 professional referee (current employer, colleague, or someone who knows you in a work context)", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "other_requirements": {"value": "Eligibility: qualifying masters in management or equivalent masters covering accounting, data analytics, economics, finance, marketing, OB, strategy (usually 5+ courses across the 7); institution EQUIS/AACSB/AMBA accredited, Russell Group or University of London member; 3-10 years experience incl. 3+ relevant. One-page CV; transcripts for every university; UK visa if needed.", "source_url": "https://www.london.edu/masters-degrees/one-year-mba/apply"}, "notes": "Aimed at applicants who already hold a masters; most Indonesian applicants with a bachelor''s only would apply to the standard MBA. Calendar dates not captured; page headings show 2028 labels."}'::jsonb,null,null),
