('London Business School','Sloan Masters in Leadership and Strategy','masters','full-time','12 or 16 months (listed duration 12 or 16 months)','December 2026 start per program page (7 December 2026); later intakes not confirmed','https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy','{"deadlines": {"value": "Rolling admissions, reviewed in order received; waitlist once class is full. No fixed round dates stated; a ''third deadline'' for visa applicants is mentioned without a date.", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "application_fee": {"value": "GBP 160 (paid after submission; waivers for LBS/University of London graduates and some others)", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "tests": {"value": "No test needed for initial application; Executive Assessment encouraged, GMAT/GRE accepted; no minimum; waivers for senior executives or CFA holders; Committee may still require EA/GMAT/GRE or online course.", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "english": {"ielts_min": "6.5 overall, 6.0 each component", "toefl_min": "86 overall, 20 each section (another LBS Sloan sheet lists 92)", "duolingo": "accepted (DET min 125 overall, 115 each component)", "pte_min": "75 overall, 67 each component", "other_tests": "Cambridge CAE/CPE 176 overall, 169 each component", "waiver": "Not needed for native-speaker nationals of majority English-speaking countries; committee may waive for 2+ years professional work in such a country or full-time degree taught in English in such a country. Tests valid 2 years.", "source_url": "https://assets.london.edu/hxo16fanegqh/50hTbXG6Jkh2gGDmGoJMzc/35555599674c5c3c101ca7b68d428b52/English_Language_Info_Sheet__1_.pdf"}, "essays": {"items": [{"prompt": "Please provide a personal statement explaining how you will contribute to the experience of others on the programme (page wording begins this way; benefit to you also asked)", "limit": "600 words", "required": true}, {"prompt": "Describe what it would mean to you personally to be an alumnus of London Business School (page wording begins this way)", "limit": "600 words", "required": true}], "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "video_assessment": {"value": "Shortlisted candidates complete a Kira video assessment.", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "interview": {"value": "Candidates passing the video stage interview with senior admissions staff or Sloan alumni.", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "recommendations": {"value": "1 reference (current/previous manager, colleague, or someone who knows your professional work)", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "other_requirements": {"value": "CV up to 2 pages; organisational chart of your division; undergraduate and graduate transcripts (certified translation; originals before enrolment); aimed at experienced executives, professionals and entrepreneurs.", "source_url": "https://www.london.edu/masters-degrees/sloan-masters-in-leadership-and-strategy/apply"}, "notes": "Aimed at senior professionals; confirm eligibility. Dates on page conflict (December 2026 vs 2027). Non-EEA nationals need a UK study visa."}'::jsonb,null,null),
('HEC Paris','MBA','mba','full-time',null,'January or September (2026-27 cycle shown; exact start dates not stated)','https://www.hec.edu/en/mba-executive-mba/mba','{"deadlines": {"value": "2026-27 cycle: R1 20 Sep 2026; R2 18 Oct 2026; R3 15 Nov 2026; R4 11 Jan 2027; R5 15 Feb 2027; R6 15 Mar 2027; R7 12 Apr 2027; R8 17 May 2027; R9 14 Jun 2027; then rolling (decision 30 Jul 2027). Decisions about 5 weeks after each deadline. Apply once per cycle (Sept intake plus following Jan intake).", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/application-deadlines"}, "application_fee": {"value": "EUR 200, non-refundable", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements"}, "tests": {"value": "GMAT, GMAT Focus, EA or GRE accepted; no minimum set (class average 635 GMAT Focus / 690 former edition). Scores under 5 years old (GRE valid 5 years after year of test). Top-ranked Master in Management holders may qualify for a waiver; contact admissions. Codes: GMAT 0TL-6C-28, GRE 0649.", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements"}, "english": {"ielts_min": "7.0 overall, 6.5 each part", "toefl_min": "CEFR C1 (5 out of 6 points)", "duolingo": "accepted (min 135)", "pte_min": "72", "other_tests": "TOEIC 340 Speaking & Writing and 850 Listening & Reading; Cambridge English (First, Advanced, Proficiency, Business) 185 overall, 176 each part", "waiver": "Required for non-native speakers without a degree taught in English. Results under 2 years old.", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements"}, "essays": {"items": [], "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements", "note": "Requirements checklist lists ''Completed Essays'' as required; prompts and limits are not published on the public page (see application portal)."}, "video_assessment": null, "interview": {"value": "Two separate interviews with HEC Paris MBA alumni, in English, equal weight. Each includes a 10-minute oral presentation on a topic of your choice followed by in-depth discussion of the application. Held in the two weeks before the final Admissions Jury.", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/how-do-i-apply"}, "recommendations": {"value": "Two recommendations", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements"}, "other_requirements": {"value": "Online application form; professional resume in English; passport-style photo; transcripts from all post-secondary institutions; passport copy or birth certificate. Undergraduate degree expected; strongly encouraged 2+ years professional experience, no absolute minimum. Degree may be waived with secondary certificate plus 5 years experience (3 managerial).", "source_url": "https://www.hec.edu/en/mba-executive-mba/mba/admissions/requirements"}, "notes": "Essay prompts not published on the requirements page (checklist says ''Completed Essays''; view in online application form). Interview and video assessment details not found on fetched pages. Duration not stated on pages fetched. Scores of IELTS/TOEFL must be under 2 years old. Student visa/housing: school recommends applying early."}'::jsonb,'{"class_label": "MBA Class of 2025 (brochure; earlier 2023 report said avg GMAT 690, so 635 may be misread - verify)", "gmat_avg": 635, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 6, "work_exp_range": null, "class_size": 235, "international_pct": 95, "women_pct": 40, "countries": 49, "pct_submitted_gre": null, "source_url": "https://www.hec.edu/sites/default/files/documents/HEC-Paris_MBA_Brochure-2025_2Mo.pdf", "source_name": "HEC Paris MBA Brochure 2025 (avg age 30; text extraction uncertain for GMAT/work exp)"}'::jsonb,'{"report_label": "MBA Class of 2025 employment statistics page", "employed_3_months_pct": 75, "median_base_salary": null, "mean_base_salary": null, "top_industries": "Technology, Finance, Consulting key sectors (no percentages on page)", "top_employers": null, "international_employed_note": "75% accepted offers within 3 months. 95% international, 49 nationalities; 64% working outside home country; jobs: Europe 52%, Asia/Oceania 25%, N. America 11%. Salary/employers not on page. Class of 2023 report: 91% within 3 months, average package USD 123,911.", "source_url": "https://www.hec.edu/en/mba-programs/mba/career/employment-statistics", "source_name": "HEC Paris MBA Employment Statistics page"}'::jsonb),
