('Cambridge Judge','MBA','mba','full-time','1 year','September 2027','https://www.jbs.cam.ac.uk/masters-degrees/mba/','{"deadlines": {"value": "2027 entry: R1 24 Aug 2026 (virtual interview day 25 Sep; interviews 28 Sep-9 Oct); R2 5 Oct 2026 (6 Nov; 9-20 Nov); R3 4 Jan 2027 (12 Feb; 15 Feb-12 Mar); R4 22 Mar 2027 (16 Apr; 19-30 Apr); R5 4 May 2027 (28 May; 1-11 Jun).", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "application_fee": {"value": "GBP 165 (online with application). Reservation fee on accepting offer GBP 7,950, non-refundable, credited to tuition.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "tests": {"value": "GMAT (either format), GRE or EA accepted; no minimum stated. Averages: GMAT current c.635, previous c.710; GRE 75% verbal / 62% quant. Scores valid 5 years at time of application. Codes: GMAT WF1-T3-68; GRE 0832.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "english": {"ielts_min": "minimum scores not stated on pages fetched (in 2026-27 MBA English language policy PDF, not read)", "toefl_min": "not stated on pages fetched", "duolingo": "not stated", "pte_min": null, "other_tests": "Accepted: IELTS Academic, IELTS for UKVI Academic, IELTS One Skill Retake, TOEFL iBT, TOEFL iBT Home Edition", "waiver": "Non-native speakers must test within 2 years before September of entry year; waiver criteria not stated", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/faqs/"}, "essays": {"items": [{"prompt": "Careers objectives statement: short- and long-term career objectives and how the MBA will help; research into how the short-term industry, role or location recruits MBA talent and what it looks for; confidence in meeting the short-term goal, existing relevant skills and current preparation", "limit": "500 words", "required": true}, {"prompt": "A time you made a professional mistake and how it could have ended differently", "limit": "200 words", "required": true}, {"prompt": "The best team you worked with and what made it successful", "limit": "200 words", "required": true}, {"prompt": "An example of someone who positively impacted your life and what you learned", "limit": "200 words", "required": true}], "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "video_assessment": {"value": "None mentioned on apply or FAQ pages", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "interview": {"value": "Shortlisted applicants notified within 3 weeks; all admissions interviews virtual (two-week window per round); also invited to a virtual interview day with admissions, careers team, students and alumni.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "recommendations": {"value": "One reference from a current or former direct supervisor/manager; academic, relative, peer or colleague references not accepted.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "other_requirements": {"value": "Good 2:1 UK Honours degree or international equivalent (master''s optional); at least 2 years full-time work by programme start (class average about 6); online application, financial guarantee on offer. Fake documents or agent-submitted false information lead to withdrawal.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mba/apply/"}, "notes": "Non-UK/Irish nationals normally need a UK student visa. Reservation fee GBP 7,950 due on accepting offer. Check the 2026-27 MBA English language policy PDF for exact IELTS/TOEFL minimums."}'::jsonb,'{"class_label": "Class of 2026 (page figures: 222 students)", "gmat_avg": 690, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 6, "work_exp_range": null, "class_size": 222, "international_pct": 90, "women_pct": 47, "countries": 43, "pct_submitted_gre": null, "source_url": "https://www.jbs.cam.ac.uk/programmes/mba/class-profile/", "source_name": "Cambridge Judge MBA class profile (avg age 29; ''Non-British ~90%''; GMAT mean; no range; nationalities 43 per class-of-2026 article). Class of 2025: 217 students, GMAT 700, 47% women, age 29"}'::jsonb,'{"report_label": "MBA Employment Report 2026 (class of 2024/25)", "employed_3_months_pct": 73, "median_base_salary": null, "mean_base_salary": "GBP 71,216 (average; USD 134,357 PPP)", "top_industries": "Finance 23%, Industry-Tech 18%, Consulting 17%, Industry-Other 14%, Healthcare/Pharma 7%, Internet/eCommerce 6%", "top_employers": "BCG, Bayer, PwC, TikTok", "international_employed_note": "73% employed at 3 months; 80% held offers; 45% switched country; UK 43% of jobs. Other page version says 82% of those seeking got offers within 4 months. No visa info.", "source_url": "https://www.jbs.cam.ac.uk/wp-content/uploads/2026/04/hdn-mba-2026-employment-report.pdf", "source_name": "Cambridge Judge MBA Employment Report 2026"}'::jsonb),
('Cambridge Judge','Master of Finance (MFin)','masters','full-time','12 months','September 2027 (mid-September)','https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/','{"deadlines": {"value": "Rolling review; final application deadline 31 May 2027 (both references also due by then). Review within about 2 weeks of complete application.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "application_fee": {"value": "GBP 120", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "tests": {"value": "GMAT/GRE not mandatory; may help if academic record is borderline or degree is non-finance. No minimum.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "english": {"ielts_min": "7.0 overall; 7.0 in Speaking, Listening, Writing; 6.5 Reading", "toefl_min": "100 overall, no section below 25 (taken before Jan 2026); page lists ''5.5'' with two sub-scores at 5.5+ and none below 5.0 for tests after Jan 2026 (unclear)", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "None described; required if English is not first language; test within 2 years of start", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "essays": {"items": [{"prompt": "Career objectives (personal statement): give a reasonably clear idea of your future career aspirations and how you expect the MFin to help you meet them; share your influences, passions, values and aspirations.", "limit": "500 words (longer statements will not be read)", "required": true}, {"prompt": "Additional information: any aspect of your candidacy that needs further explanation, or anything you want the Admissions Committee to know.", "limit": "300 words", "required": false}], "source_url": "https://www.jbs.cam.ac.uk/wp-content/uploads/2026/10/mfin-application-guidance-notes-2027.pdf", "note": "From the MFin application guidance notes (2027 file). Also short-answer fields without stated limits: work experience, how you will fund the programme, how you heard about MFin, other universities considered."}, "video_assessment": {"value": "No video submission required; only a live video interview for shortlisted candidates", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "interview": {"value": "Held on a set day each month by video call with MFin Director or Finance faculty; candidates may request Cambridge in person. Shortlisted by email.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "recommendations": {"value": "Professional reference from current line manager (work email) plus academic reference; if unavailable explain in Additional Information.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "other_requirements": {"value": "High UK 2:1 or equivalent in any subject (e.g. US GPA 3.6/4.0, higher than University standard for overseas); 2+ years graduate-level finance work by start, ideally 1 year front office; transcript (front and back) uploaded, originals on offer; optional CV review.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/master-of-finance/apply/"}, "notes": "Statements part of the application but prompts/limits not on page (see linked guidance notes PDF, not read). Non-UK/Irish nationals need student visa; CAS issued from June with unconditional offer; first fee instalment 10% and second 20% by 15 May or unconditional offer date."}'::jsonb,'{"class_label": "MFin class of 2025", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 5, "work_exp_range": null, "class_size": 106, "international_pct": null, "women_pct": null, "countries": 38, "pct_submitted_gre": null, "source_url": "https://www.jbs.cam.ac.uk/2025/meet-the-cambridge-mfin-class-of-2025/", "source_name": "Cambridge Judge: Meet the MFin class of 2025 (no GMAT stated)"}'::jsonb,'{"report_label": "MFin 2024 (2024/25 graduating class) employment report 2026", "employed_3_months_pct": 85, "median_base_salary": null, "mean_base_salary": null, "top_industries": "Finance 74% (VC/PE 25%, IB 21%, asset mgmt 18%), Industry 13%, Consulting 11%, NGO 2%", "top_employers": null, "international_employed_note": "85% employed at 3 months (94% had an offer); 31 nationalities; 12 countries; 50% returned to home country; 39% of roles in Asia. Salary not reported.", "source_url": "https://www.jbs.cam.ac.uk/2026/the-master-of-finance-employment-report-2026/", "source_name": "Cambridge Judge MFin Employment Report 2026"}'::jsonb),
('Cambridge Judge','MSt in Entrepreneurship','masters','part-time','21 months (blended, 4 one-week residentials)','September 2027','https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/','{"deadlines": {"value": "Applications open 15 Sep 2026. R1 30 Nov 2026; R2 15 Mar 2027 (deadline for non-standard applicants); R3 13 May 2027 (final). Interviews within about 8 weeks of each deadline.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "application_fee": {"value": "GBP 85 on application/requirements sections; FAQ states non-refundable GBP 120 (page conflicts)", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "tests": {"value": "GMAT/GRE normally not required; required (above 50th percentile verbal and quant) if no UK 2:1 or equivalent and no postgraduate degree. Codes GMAT WF1-T3-81, GRE 7020.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "english": {"ielts_min": "7.5 overall, 7.0 each element, same sitting within past 2 years", "toefl_min": "110 overall, 25 each element (incl. Home Edition); tests after 21 Jan 2026 may need extra Language Centre assessment", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Nationals of majority English-speaking countries (UKVI) and/or educated there for undergraduate degree. No need to test before applying; asked if offered.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "essays": {"items": [], "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/", "note": "The application includes short questions on entrepreneurial experience, past ventures, future goals and what you hope to get from the course; exact wording and limits are not published on the page. Optional King''s College personal statement: no longer than one A4 page."}, "video_assessment": {"value": "No video required in application (YouTube video on page is promotional)", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "interview": {"value": "Shortlisted candidates have a video interview with Programme Director or faculty; assesses fit, not English.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "recommendations": {"value": "2 referees, ideally one academic, one professional (two professional acceptable); may arrive after application but before interview.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "other_requirements": {"value": "UK 2:1 honours or equivalent (below that considered with relevant postgraduate); transcripts of all courses; evidence of entrepreneurial experience; short application questions on experience, ventures, goals; King''s College applicants need a 1-page statement.", "source_url": "https://www.jbs.cam.ac.uk/masters-degrees/mst-entrepreneurship/apply/"}, "notes": "No visa sponsorship: Non-UK/Irish nationals enter as visitors for residentials. Short questions have no published prompts or word limits."}'::jsonb,null,null),
