('Oxford Saïd','Oxford MBA','mba','full-time','1 year','Sept 2027 (2027-28)','https://www.sbs.ox.ac.uk/application-requirements','{"deadlines": null, "application_fee": {"value": "GBP 150, paid at submission", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "tests": {"value": "GMAT or GRE required for all applicants. Original GMAT and GMAT Focus both accepted. No minimum; 650+ GMAT considered competitive (class median 690); GRE 160V/160Q competitive (median 160 each).", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not stated", "pte_min": null, "other_tests": "Accepted: TOEFL (institution code 0807), IELTS Academic, Cambridge C1 Advanced, C2 Proficiency; all taken less than 2 years before course start. Minimum scores not stated on this page.", "waiver": "Required for nationals of non-majority-English-speaking countries (per UKVI). Waiver at Admissions Committee discretion via qualifying degree-level course or substantial professional use of English; criteria not listed.", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "essays": {"items": [], "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "video_assessment": {"value": "Kira Talent online assessment, 4 questions, up to 30 minutes: 2 motivation (why MBA, why Oxford), 1 competency-based, 1 not described. Link appears in status portal within 24 hours of submission. Needs laptop/desktop with webcam and mic.", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "interview": {"value": "No live interview described. Applicants complete a Kira Talent online assessment: four questions (motivation and one competency-based), up to 30 minutes, link emailed up to 24 hours after submission. NOTE: the cited page is labelled class of 2024-25; confirm for the current cycle.", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "recommendations": {"value": "Two references, preferably professional (or academic). Must use work/institutional email; Gmail/Hotmail not accepted.", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "other_requirements": {"value": "Min. 2 years full-time work experience; one-page CV; recognised undergraduate degree; transcripts for all degrees with official translation if not in English. Supporting statement covering post-MBA plans. School may spot-check references, work experience and academic records.", "source_url": "https://www.sbs.ox.ac.uk/application-requirements"}, "notes": "The page does not give exact essay prompts (see application form) and does not mention a live interview. The only 2026-27 round dates found were on third-party Clear Admit (R1 2 Sep 2026, R2 5 Oct, R3 4 Nov, R4 6 Jan 2027, R5 25 Mar 2027), not recorded as official; the official how-apply-mba page fetched was a stale 2016 cycle page. Confirm dates on sbs.ox.ac.uk."}'::jsonb,'{"class_label": "Oxford MBA FAQ page: GMAT/GRE for 2023-24 class; demographics for 2022-23 cohort", "gmat_avg": null, "gmat_median": 680, "gmat_range": "Median 680 for 2023-24 class; median 690 over last four years (Classic/unspecified; no range published on page)", "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "Median V 159, Q 160 (2023-24); medians not averages", "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 5, "work_exp_range": "Minimum 2 years full-time post-graduation", "class_size": null, "international_pct": 93, "women_pct": 48, "countries": 64, "pct_submitted_gre": null, "source_url": "https://sbs.ox.ac.uk/programmes/mbas/mba/faqs", "source_name": "Oxford Saïd MBA FAQs (international 93% and women 48%, 64 nationalities are 2022-23 cohort)"}'::jsonb,'{"report_label": "MBA 2024/25 employment report (class of 339 graduates)", "employed_3_months_pct": 75, "median_base_salary": null, "mean_base_salary": "GBP 81,466 (up 9.9%); average bonus GBP 15,985; 94% reported salary", "top_industries": "Financial services 38.6%, Consulting 22.2%, Global industry 21.5%, Technology and e-commerce 13.3%, Impact 4.4%; 8.6% of class started own venture", "top_employers": "McKinsey, BCG, Bain, Deloitte, Roland Berger; JP Morgan, Barclays, BlackRock, Citi UK, Revolut, World Bank; Unilever, Toyota, Mercedes-Benz, Nike, ExxonMobil, SpaceX; Amazon, ByteDance/TikTok, PlayStation, Kyndryl", "international_employed_note": "75% = graduates seeking a role who received an offer within 90 days (about 22.7% of reporters not seeking employment). 97% of class international, 63 nationalities. Placement: UK 48%, North America 14%, Asia 12%, Europe 9%. Mean base by region: North America GBP 116,827, Asia GBP 40,399. 88% switched sector/country/function. No visa/sponsorship info in report.", "source_url": "https://www.sbs.ox.ac.uk/sites/default/files/2026-06/mba-employment-report-25.pdf", "source_name": "Oxford Saïd MBA Employment Report 2025"}'::jsonb),
('Oxford Saïd','Oxford 1+1 MBA','mba','full-time','2 years (1-year partner master''s + 1-year MBA)','Sept 2027','https://www.sbs.ox.ac.uk/programmes/mbas/oxford-11-mba','{"deadlines": {"value": "Oxford MBA component: January deadline, Wednesday 6 January 2027 (2027-28 intake). Partner master''s deadline set by each programme (January).", "source_url": "https://www.sbs.ox.ac.uk/programmes/mbas/oxford-11-mba"}, "application_fee": {"value": "GBP 75 per application (MBA and master''s each charged)", "source_url": "https://www.sbs.ox.ac.uk/oxford-11-mba-faqs"}, "tests": {"value": "GMAT or GRE required, weighed equally (35% of latest MBA cohort took the GRE). No minimum stated.", "source_url": "https://www.sbs.ox.ac.uk/oxford-11-mba-faqs"}, "english": null, "essays": {"items": [{"prompt": "Essay explaining why the 1+1 suits you (prompt text not given on page)", "limit": "250 words", "required": true}], "source_url": "https://www.sbs.ox.ac.uk/programmes/mbas/oxford-11-mba"}, "video_assessment": {"value": "Online assessment required for MBA component (per page)", "source_url": "https://www.sbs.ox.ac.uk/programmes/mbas/oxford-11-mba"}, "interview": {"value": "Interview if shortlisted (MBA component)", "source_url": "https://www.sbs.ox.ac.uk/programmes/mbas/oxford-11-mba"}, "recommendations": {"value": "MBA welcomes professional references; can reuse master''s referees. Partner master''s often require 3 academic references.", "source_url": "https://www.sbs.ox.ac.uk/oxford-11-mba-faqs"}, "other_requirements": {"value": "Meet entry requirements of both MBA and chosen master''s (one of 14 departments) and apply to each separately; min 2 years work experience (less may be considered); written statement. Pershing Square Scholarship covers fees for up to 6 students/yr. MBA 2027-28 tuition GBP 94,120.", "source_url": "https://www.sbs.ox.ac.uk/oxford-11-mba-faqs"}, "notes": "Intake years on the page (Sept 2026 and Sept 2027); English requirements not on these pages, follow partner master''s and MBA requirements. Page says up to 6 Pershing Square scholars; the about page says up to 5."}'::jsonb,null,null),
