('IESE','MBA','mba','full-time','15 or 19 months (Traditional or Flexible track, per overview page)','September 2027 (page also says Class of 2029)','https://www.iese.edu/mba/','{"deadlines": {"value": "R1 23 Sep 2026; R2 7 Jan 2027; R3 9 Mar 2027; R4 6 May 2027. Interview decisions 9 Oct / 22 Jan / 19 Mar / 14 May; final decisions 23 Nov 2026 / 15 Mar / 30 Apr / 11 Jun 2027.", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "application_fee": {"value": "EUR 200, non-refundable", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "tests": {"value": "GMAT or GRE mandatory for all candidates; scores up to 5 years old; if both taken, submit both. No minimum stated.", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "english": {"ielts_min": "7.5 (recommended)", "toefl_min": "100 iBT (recommended); post-Jan 2026 format accepted on 0-120 scale", "duolingo": "not stated", "pte_min": "68 (C1)", "other_tests": "Cambridge Certificate of Proficiency, minimum level B", "waiver": null, "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "essays": {"items": [], "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "video_assessment": {"value": "Kira: 4 video questions; link sent within 24 hours of submitting application and fee; must be done by round deadline, link expires 48 hours after receipt; application not reviewed until completed", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "interview": {"value": "Personal interview in English: Barcelona campus, videoconference, or with an admissions director during regional travel. Optional Assessment Day (strongly recommended, not required).", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "recommendations": {"value": "One letter of recommendation", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "other_requirements": {"value": "Online application; official transcripts; CV; undergraduate degree required; passport-size photo (max 2 MB); military/civil service obligation item; documents in English. Typical 5 years work experience (FAQ on program page).", "source_url": "https://www.iese.edu/mba/admissions-fees/"}, "notes": "Mandatory essays via online form; prompts and word limits not on the page. The admissions page mixes Sept 2027 and Class of 2029 labels and shows a 7 Sep 2026 term start; confirm intake with IESE. Duration is stated as 15 or 19 months on the overview page while the FAQ describes a 2-year program. Apply via https://iese.embark.com/apply/mba-2029."}'::jsonb,'{"class_label": "Class of 2027 (class size, nationalities, women, international from IESE story); other figures from IESE MBA class profile page (year not stated)", "gmat_avg": null, "gmat_median": null, "gmat_range": "Acceptance range 545-715 on GMAT Focus (previous GMAT Classic range 580-750); not stated whether middle 80%", "gmat_focus_median": null, "gmat_focus_range": "545-715", "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 5.4, "work_exp_range": "60% 3-6 yrs, 30% 6-10 yrs, 5% 10+ yrs, 5% 2-3 yrs", "class_size": 421, "international_pct": 88, "women_pct": 38, "countries": 56, "pct_submitted_gre": null, "source_url": "https://www.iese.edu/stories/iese-mba-mim-class-diverse-global/", "source_name": "IESE story (421/56/38%/88%); also https://www.iese.edu/mba/class-profile/ (profile page shows 370+, 89% intl, 50+ countries, avg age 29)"}'::jsonb,'{"report_label": "Class of 2025 MBA (2024-25 cycle)", "employed_3_months_pct": 80, "median_base_salary": null, "mean_base_salary": null, "top_industries": "Consulting 41%, Diversified industries 33%, Finance 16%, Technology 9%", "top_employers": "Accenture, Almirall, Amazon, Bain, BCG, Fever, Google, Kearney, McKinsey, Strategy&", "international_employed_note": "Not found. Salary not on the page (full report is behind a form: formscloud.iese.edu/landings-mba-employment).", "source_url": "https://www.iese.edu/stories/iese-mba-career-impact/", "source_name": "IESE MBA career impact page"}'::jsonb),
('IESE','Master in Management (MiM)','masters','full-time','11 months','September 2027 (apply link labelled mim2028)','https://www.iese.edu/master-in-management/','{"deadlines": {"value": "Monthly rolling rounds: 2 Oct 2026; 6 Nov; 11 Dec; 15 Jan 2027; 22 Feb; 26 Mar; 2 May; 4 Jun. Non-EU passport holders must apply before 1 May (Spanish immigration policy), so rounds 7 and 8 are not available to them. Decisions about 4-6 weeks after submission.", "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "application_fee": {"value": "EUR 180, paid via Embark", "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "tests": {"value": "GMAT, GRE or IESE Test listed as required document; page does not say whether any is preferred or waivable. Program page: either GMAT, GRE, or the IESE Test (similar to GMAT).", "source_url": "https://www.iese.edu/master-in-management/"}, "english": {"ielts_min": "7.0", "toefl_min": "100 iBT", "duolingo": "not stated", "pte_min": null, "other_tests": "Cambridge Proficiency", "waiver": null, "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "essays": {"items": [], "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "video_assessment": null, "interview": {"value": "Required; virtual or in person at Madrid campus; in English", "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "recommendations": {"value": "One recommendation letter (per program page; not mentioned on admissions-fees page)", "source_url": "https://www.iese.edu/master-in-management/"}, "other_requirements": {"value": "Online application, official transcripts, CV, passport-size photo; official university degree. Targets recent graduates with 0-2 years experience. Tuition EUR 55,500; EUR 10,000 commitment fee after admission.", "source_url": "https://www.iese.edu/master-in-management/admissions-fees/"}, "notes": "Mandatory essays via online form; prompts not published on the page. Non-EU applicants (Indonesians) must apply before 1 May 2027. Visa documents needed after admission."}'::jsonb,'{"class_label": "Class of 2026", "gmat_avg": null, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": null, "work_exp_range": "0-2 years", "class_size": 149, "international_pct": 74, "women_pct": 48, "countries": 31, "pct_submitted_gre": null, "source_url": "https://www.iese.edu/stories/iese-mba-mim-class-diverse-global/", "source_name": "IESE story on MBA and MiM classes"}'::jsonb,null),
