('IESE','Master in Research in Management (MRM)','masters','full-time','2 years (120 ECTS)','September 2027','https://www.iese.edu/master-research-management/','{"deadlines": {"value": "First-round deadline 20 January 2027, 11:59 PM CET; applications for Sept 2027 open October 2026", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "application_fee": {"value": "EUR 40, non-refundable, paid via Flywire", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "tests": {"value": "GMAT or GRE compulsory, no waivers; no minimum; unofficial score enough to apply, official required if admitted. IESE codes: GMAT S21-BK-53, GRE 3607.", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "english": {"ielts_min": "7.0 Academic", "toefl_min": "95 iBT", "duolingo": "not stated", "pte_min": "68 (C1)", "other_tests": "Cambridge English Grade A or B", "waiver": "Request if English is mother tongue, 2 academic years with English as main language of instruction, 1 year working in an English-speaking country, or a university degree in English", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "essays": {"items": [{"prompt": "Motivation letter: what led you to want a doctorate and what draws you to academic life", "limit": "not stated", "required": true}, {"prompt": "Research interests essay: research interests and goals, why they matter, relevant literature, any research done", "limit": "not stated (short essay)", "required": true}], "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "video_assessment": null, "interview": null, "recommendations": {"value": "Two letters via IESE online system; academic letters preferred", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "other_requirements": {"value": "Bachelor''s degree; strong quantitative background; transcripts and diplomas from all post-secondary institutions (certified translation if not English/Spanish); passport copy; photo; military/civil service obligations completed. CV not mentioned.", "source_url": "https://www.iese.edu/master-research-management/requirements/"}, "notes": "Research-track degree feeding the PhD. Originals of records due within 3 months of admission."}'::jsonb,null,null),
('IMD','IMD MBA (1-year, Lausanne)','mba','full-time','1 year (Jan-Dec)','Class of 2028 (rounds listed Jan-Oct 2027); Class of 2027 still open per page','https://www.imd.org/degree/mba/','{"deadlines": {"value": "Class of 2028, six rounds (deadline / assessment day online / on-campus): 26 Jan 2027 (5 Feb / 12-13 Feb); 16 Mar 2027 (2 Apr / 9-10 Apr); 4 May 2027 (14 May / 21-22 May); 13 Jul 2027 (23 Jul / 6-7 Aug); 7 Sep 2027 (17 Sep / 24-25 Sep); 12 Oct 2027 (22 Oct). Earlier applications get decisions sooner.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "application_fee": {"value": "CHF 150, non-refundable", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "tests": {"value": "GMAT 555+ recommended, or equivalent GRE or Executive Assessment. Scores under 5 years old. GMAT code SKR-MM-13; GRE code 8490.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "No TOEFL/IELTS minimum listed. Program taught in English; for non-native speakers the Admissions team assesses English during the assessment day.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "essays": {"items": [], "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "video_assessment": {"value": "Not mentioned; assessment day is online or on campus.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "interview": {"value": "Part of assessment day (virtual or in person) with individual and group tasks.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "recommendations": {"value": "One business-related recommender who has worked with you directly, via IMD online form; enter details at least 2 weeks before deadline; professional email (no Hotmail/Gmail).", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "other_requirements": {"value": "Bachelor''s or equivalent; min 2 years full-time postgraduate work experience (typical 3-8); copies of all degree diplomas/transcripts with grading scale and official English/French translations; one-page CV on IMD template; all documents needed at submission or application may move to a later round.", "source_url": "https://www.imd.org/degree/mba/admissions/admission-process/"}, "notes": "Page lists no essay prompts or word limits; the online application has a section on why you match IMD. Tuition CHF 97,500 (program page). Executive MBA and Executive Master programs excluded per scope."}'::jsonb,'{"class_label": "Class of 2025 (P&Q/dean quote); IMD MBA 2025 profile PDF shows 78 students, 42% women", "gmat_avg": 680, "gmat_median": null, "gmat_range": "Typical range 555-755 (IMD participants page, not defined as middle 80%); P&Q class of 2025 average 680; IMD MBA page lists 615 average for a 2026 class (discrepancy, unresolved)", "gmat_focus_median": null, "gmat_focus_range": null, "gre_verbal_avg": null, "gre_quant_avg": null, "gre_range": "P&Q: class average GRE total 324", "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 6, "work_exp_range": "Typically 3-8 years (age typically 25-34, average age ~30)", "class_size": 90, "international_pct": 98, "women_pct": 42, "countries": 34, "pct_submitted_gre": null, "source_url": "https://poetsandquants.com/2025/11/20/meet-imd-business-schools-mba-class-of-2025/2/", "source_name": "Poets&Quants Meet IMD MBA Class of 2025; range/countries from https://www.imd.org/degree/mba/program/participants/; PDF https://imd.org/wp-content/uploads/2025/04/IMD_MBA_Class_Profile_2025.pdf"}'::jsonb,'{"report_label": "Class of 2025 MBA career statistics (IMD web page; downloadable stats form not accessed)", "employed_3_months_pct": null, "median_base_salary": "USD 176,000 (USD PPP), class of 2025; another IMD page labels it ''average''", "mean_base_salary": null, "top_industries": null, "top_employers": null, "international_employed_note": "78% received at least one job offer within 3 months (offer rate, not employed rate); 92% switched role, industry and/or geography; 60-70 companies recruit each year. Career stats download: https://www.imd.org/white-paper-download/?tfa_71=MBACareerStats&tfa_1112=MBA", "source_url": "https://www.imd.org/degree/mba/career/development/", "source_name": "IMD MBA career development page"}'::jsonb),
('IMD','MSc in Sustainable Management and Technology (joint with EPFL/UNIL, Lausanne)','masters','full-time','1 year','September (annual)','https://www.imd.org/msc/master-degree/sustainable-management-technology/','{"deadlines": {"value": "Two rounds: mid-November to 15 December (decisions by end of March); 16 December to 31 March (decisions by end of June). Cycle year not stated on page; applicants needing a Swiss study visa should apply by 15 December.", "source_url": "https://e4s.center/en/our-activities/education/e4s-smt-master/admission-criteria/"}, "application_fee": {"value": "CHF 150 for holders of a foreign Bachelor''s (EPFL online application page).", "source_url": "https://www.epfl.ch/education/admission/master-admission-criteria-application/online-application/"}, "tests": {"value": "No standardized test required; TOEFL and GRE scores optional. Familiarity with quantitative methods/systems thinking and programming expected (avg 5/6 in quantitative courses usual).", "source_url": "https://e4s.center/en/our-activities/education/e4s-smt-master/admission-criteria/"}, "english": {"ielts_min": null, "toefl_min": null, "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "EPFL program page states: No proof of English proficiency is required.", "source_url": "https://www.epfl.ch/schools/cdm/college-of-management-of-technology/education/masters/master-sustainable-management-technology/"}, "essays": {"items": [{"prompt": "Statement of purpose: describe your academic background and career strategy and what you want to achieve through your studies at EPFL", "limit": "1,000 words max", "required": true}], "source_url": "https://www.epfl.ch/education/admission/master-admission-criteria-application/online-application/"}, "video_assessment": null, "interview": {"value": "No interview or video assessment is mentioned on the official SMT admission page. Selection is document-based: admission decided jointly by the SMT Admission Commission and EPFL''s admissions committee on GPA, letters of recommendation, background and motivation letter.", "source_url": "https://www.epfl.ch/schools/cdm/college-of-management-of-technology/education/masters/master-sustainable-management-technology/smt-application-admission/"}, "recommendations": {"value": "Three academic referees'' contact details; referees must be professors; at least 2 letters required; letters due one week after the application deadline (exemptions for EPFL/Swiss-university bachelor holders and UNIL candidates).", "source_url": "https://www.epfl.ch/education/admission/master-admission-criteria-application/online-application/"}, "other_requirements": {"value": "Bachelor''s in engineering or management/economics profile, min average grade 4.5 or equivalent; CV, transcripts of all universities, degree copy if available, ID/passport. Swiss HES/FHS holders not eligible. One master''s application per year.", "source_url": "https://www.epfl.ch/education/master/programs/sustainable-management-and-technology/"}, "notes": "Fee, statement of purpose and referees come from the EPFL central application pages. Bachelor''s, not MBA-type experience, is the target. Swiss study visa can take up to 3 months, apply by 15 Dec. Intensive French course offered before semester. Executive Masters at IMD excluded per scope."}'::jsonb,null,null),
('NUS','NUS MBA (full-time)','mba','full-time','12 to 17 months','August 2027','https://mba.nus.edu.sg/','{"deadlines": {"value": "August 2027 intake: Round 1 29 Oct 2026; Round 2 20 Jan 2027; Round 3 31 Mar 2027; rolling review; applications open 1 Sep 2026.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "application_fee": {"value": "S$100 (applications without fee not processed)", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "tests": {"value": "From the August 2027 intake, GMAT, GRE or Executive Assessment accepted in all formats; score valid at least one month from submission; IR scores considered for GMAT/EA. Waivers case-by-case, e.g. 4+ years full-time experience and strong profile.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "english": {"ielts_min": "7.0 overall", "toefl_min": "100 iBT", "duolingo": "not stated", "pte_min": null, "other_tests": null, "waiver": "Case-by-case for applicants without an English-taught degree who have 5+ years in an English-speaking environment", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "essays": {"items": [{"prompt": "How have people, events, and/or situations in your life influenced who you are today?", "limit": "250 words", "required": true}, {"prompt": "How do you plan to spend your time on the MBA to transform yourself personally and professionally? Briefly describe your experience to date, and how this and the MBA can help you achieve your mid and long-term career goals.", "limit": "250 words", "required": true}, {"prompt": "Describe a situation where you turned a challenging personal or professional scenario into an opportunity for success, detailing how your insights, adaptability, and decision-making skills played a crucial role.", "limit": "250 words", "required": true}], "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "video_assessment": {"value": "Required (Stage 3): one-way video, 1 practice then 1 attempt at one question; 30 seconds prep, up to 3 min recording; complete within 3 days of invitation; supplements the live interview.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "interview": {"value": "Shortlisted candidates only: 30-minute online interview 2-4 weeks after video assessment; decision about 2 weeks later.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "recommendations": {"value": "One referee report, submitted before link expires and before deadline.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "other_requirements": {"value": "Bachelor''s degree; 2+ years full-time post-degree work experience; S$15,000 acceptance fee on admission; scholarship box on form; NUS does not use agents.", "source_url": "https://mba.nus.edu.sg/admissions-and-funding/"}, "notes": "Duration range 12-17 months for full-time is from mba.nus.edu.sg/apply-now/. Double Degree Programmes (e.g. HEC Paris) need separate applications to NUS and partner; other partners not listed on the page. Check Round 1 date has passed (today 16 Nov 2026) so Round 2 or 3 apply to Indonesian applicants now."}'::jsonb,'{"class_label": "Full-time MBA class profile (year not labeled on page)", "gmat_avg": 670, "gmat_median": null, "gmat_range": null, "gmat_focus_median": null, "gmat_focus_range": "average GMAT Focus 615 (no range given)", "gre_verbal_avg": 157, "gre_quant_avg": 165, "gre_range": null, "gpa_avg": null, "gpa_range": null, "work_exp_avg_years": 6, "work_exp_range": null, "class_size": 120, "international_pct": 92, "women_pct": 43, "countries": 21, "pct_submitted_gre": null, "source_url": "https://mba.nus.edu.sg/who-is-it-for/", "source_name": "NUS MBA - Who is it for (class profile); also average age 29; page gives averages only, work experience unit not stated on page"}'::jsonb,'{"report_label": "NUS MBA career statistics on homepage (year not stated); career page lists Class of 2022 highlights without values", "employed_3_months_pct": 93, "median_base_salary": null, "mean_base_salary": "USD 82,095 (labeled ''average post-MBA salary'' on homepage; unclear if base or total, year not stated)", "top_industries": null, "top_employers": null, "international_employed_note": "Not given. Homepage also states 148% increase on pre-MBA salary and average alumni salary 3 years after graduation of USD 170,898.", "source_url": "https://mba.nus.edu.sg/", "source_name": "NUS MBA homepage"}'::jsonb),
