('HKUST','HKUST-NYU Stern MS in Global Finance (MSGF)','masters','part-time','1 year (12 months, six modules in Hong Kong, New York, rotating global location)','Class of 2027 deadline shown; Class of 2028 dates not found','https://msgf-nyustern.hkust.edu.hk/','{"deadlines": {"value": "Final deadline Saturday, October 17, 2026 for MSGF Class of 2027; late consideration possible case by case for applicants outside Hong Kong", "source_url": "https://msgf-nyustern.hkust.edu.hk/"}, "application_fee": {"value": "HKD 1,200 (2027/28 catalog)", "source_url": "https://prog-crs.hkust.edu.hk/pgprog/2027-28/msc-gfin"}, "tests": {"value": "GMAT and GRE not required", "source_url": "https://msgf-nyustern.hkust.edu.hk/faq"}, "english": {"ielts_min": "6.5 overall, no sub-score below 5.5", "toefl_min": "TOEFL iBT 80 (tests before 21 Jan 2026) or 4.5 (tests from 21 Jan 2026) as published; page''s 4.5 figure looks unusual, confirm with program; pBT 550", "duolingo": "not stated", "pte_min": null, "other_tests": "TOEFL Revised paper-delivered 60; single attempt, at-home not accepted", "waiver": "First language English or bachelor''s taught in English", "source_url": "https://prog-crs.hkust.edu.hk/pgprog/2027-28/msc-gfin"}, "essays": {"items": [{"prompt": "What do you hope to achieve by pursuing this degree? Given your professional background, what can you contribute to your fellow MSGF participants and the community?", "limit": "250 words", "required": true}, {"prompt": "Discuss a business challenge that you have faced. How did you address this issue, and what lessons did you learn?", "limit": "250 words", "required": true}, {"prompt": "[Optional] Why do you believe you are the best candidate for the MSGF award?", "limit": "250 words", "required": false}], "source_url": "https://fytgs.hkust.edu.hk/system/files/gfin_tips202526.pdf"}, "video_assessment": {"value": "No video requirement is mentioned in the MSGF application guidelines (guide file labelled 2025-26; cycle not stated in document).", "source_url": "https://fytgs.hkust.edu.hk/system/files/gfin_tips202526.pdf"}, "interview": {"value": "Shortlisted applicants only; 30-minute online Zoom interview with Admissions Committee", "source_url": "https://msgf-nyustern.hkust.edu.hk/faq"}, "recommendations": {"value": "Two referees; nominate with consent, use official work/university email; referees complete an online reference form.", "source_url": "https://fytgs.hkust.edu.hk/system/files/gfin_tips202526.pdf"}, "other_requirements": {"value": "Bachelor''s degree or equivalent; 5 years full-time post-bachelor work experience (slightly less considered case by case); strong quantitative skills expected. Fee HKD 682,500", "source_url": "https://prog-crs.hkust.edu.hk/pgprog/2027-28/msc-gfin"}, "notes": "Executive-style modular program for working professionals (avg ~11 years experience); a master''s degree, not an EMBA, so included. Essays and recommendations not found. Check for Class of 2028 deadlines."}'::jsonb,null,null),
